/**
 * Phase 4 Pipeline -- Stage 5: HTTP Server Generator
 *
 * Generates Cloud Run-compatible HTTP server code for the resolved implementation
 * language and framework. Produces main entrypoint, route handlers, middleware,
 * health check endpoints, DI factory, and Zod validation schemas derived from
 * Phase 2 bounded context definitions.
 *
 * TypeScript target: Hono framework with structured JSON logging.
 * Rust target: Axum framework with Tower middleware layers.
 *
 * All generated files carry a "do not edit manually" header.
 *
 * Exports:
 *   - generateHttpServer(context) -- pipeline entry point
 *
 * Error codes:
 *   ECLI-P4-050  Missing prerequisite stage output (erp-target-resolution)
 *   ECLI-P4-051  HTTP server file write failure
 */

import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import type {
  Phase4Context,
  Phase4StageOutput,
  HttpServerOutput,
  ServerFile,
  ERPResolution,
} from '../types.js';
import { hasTemplateSupport } from '../types.js';
import { createSpan, endSpan, emitSpan } from '../../phase2/telemetry.js';

// ============================================================================
// Constants
// ============================================================================

const DIR_MODE = 0o700;
const FILE_MODE = 0o600;
const GENERATED_HEADER_TS = '// Generated by Phase 4 pipeline — do not edit manually\n';
const GENERATED_HEADER_RS = '// Generated by Phase 4 pipeline — do not edit manually\n';

// ============================================================================
// Name Helpers
// ============================================================================

function slugify(name: string): string {
  return name
    .replace(/([a-z])([A-Z])/g, '$1-$2')
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .toLowerCase();
}

function snakeCase(name: string): string {
  return slugify(name).replace(/-/g, '_');
}

function pascalCase(name: string): string {
  return name
    .replace(/[-_\s]+(.)?/g, (_, c: string | undefined) => (c ? c.toUpperCase() : ''))
    .replace(/^(.)/, (_, c: string) => c.toUpperCase());
}

function camelCase(name: string): string {
  const p = pascalCase(name);
  return p.charAt(0).toLowerCase() + p.slice(1);
}

// ============================================================================
// DDD Context Type (passed from call site)
// ============================================================================

interface DDDContext {
  name: string;
  commands: { name: string; description?: string; input?: readonly string[]; preconditions?: readonly string[]; postconditions?: readonly string[] }[];
  queries: { name: string; description?: string; parameters?: readonly string[]; returns?: string }[];
  entities: { name: string; description: string }[];
  valueObjects: { name: string; description: string }[];
  domainEvents: { name: string; description?: string; payload?: readonly string[]; triggeredBy?: string }[];
  invariants: string[];
}

// ============================================================================
// TypeScript / Hono Generation — Domain Logic Routes
// ============================================================================

/**
 * Generate the TypeScript main.ts entrypoint for Hono on Cloud Run.
 */
function tsMain(): string {
  return [
    GENERATED_HEADER_TS,
    `import { serve } from '@hono/node-server';`,
    `import { app } from './routes.js';`,
    '',
    'const PORT = parseInt(process.env.PORT ?? \'8080\', 10);',
    '',
    'serve({ fetch: app.fetch, port: PORT }, (info) => {',
    '  process.stdout.write(',
    '    JSON.stringify({',
    '      severity: \'INFO\',',
    '      message: \'HTTP server started\',',
    '      port: info.port,',
    '      pid: process.pid,',
    '      timestamp: new Date().toISOString(),',
    '    }) + \'\\n\',',
    '  );',
    '});',
    '',
    'process.on(\'SIGTERM\', () => {',
    '  process.stdout.write(',
    '    JSON.stringify({',
    '      severity: \'INFO\',',
    '      message: \'Received SIGTERM — shutting down gracefully\',',
    '      timestamp: new Date().toISOString(),',
    '    }) + \'\\n\',',
    '  );',
    '  process.exit(0);',
    '});',
    '',
  ].join('\n');
}

/**
 * Generate Zod validation schemas dynamically from DDD bounded contexts.
 * One schema per command (POST body) and one per query (GET params).
 */
/**
 * Infer the Zod schema type for a field based on its name.
 * Returns the z.* expression as a string.
 */
function inferZodType(fieldName: string, required: boolean): string {
  const lower = fieldName.toLowerCase();
  const opt = required ? '' : '.optional()';

  // Numeric fields
  if (/amount|price|cost|fee|rate|total|balance|value|score|rating|weight|percentage|pct/.test(lower))
    return `z.coerce.number()${opt}`;
  if (/quantity|count|number|version|level|priority|minutes|hours|days|seconds|attempts|retries/.test(lower))
    return `z.coerce.number().int()${opt}`;

  // Boolean fields
  if (/^is[A-Z_]|^has[A-Z_]|enabled|active|valid|flag|approved|completed|cancelled|deleted/.test(fieldName))
    return `z.coerce.boolean()${opt}`;

  // Date/time fields
  if (/date|deadline|expires|timestamp|_at$|created|updated|scheduled/.test(lower))
    return `z.string().datetime({ offset: true })${opt || '.optional()'}`;

  // Email/URL
  if (/email/.test(lower)) return `z.string().email()${opt}`;
  if (/url|link|uri|endpoint/.test(lower)) return `z.string().url()${opt}`;

  // ID fields — required string with min length
  if (/id$|_id$|ref$|uuid|key/.test(lower))
    return required ? `z.string().min(1)` : `z.string().optional()`;

  // Default: string
  return required ? `z.string().min(1)` : `z.string().optional()`;
}

/**
 * Infer typed default fields for a command when the DDD model has no explicit input fields.
 * Uses the command name and context name to produce domain-relevant Zod fields.
 */
function inferDefaultCommandFields(cmdName: string, contextName: string): string[] {
  const lower = cmdName.toLowerCase();
  const ctxLower = contextName.toLowerCase();
  const entityId = `${snakeCase(contextName)}_id`;

  // Base fields every command needs
  const fields: string[] = [`  ${entityId}: z.string().uuid(),`];

  // Add fields based on command verb
  if (/^create|^add|^register|^submit/.test(lower)) {
    fields.push(`  name: z.string().min(1).max(255),`);
    fields.push(`  description: z.string().max(2000).optional(),`);
    fields.push(`  metadata: z.record(z.unknown()).optional(),`);
  } else if (/^update|^modify|^patch|^edit/.test(lower)) {
    fields.push(`  updates: z.record(z.unknown()),`);
    fields.push(`  reason: z.string().min(1).optional(),`);
  } else if (/^delete|^remove|^cancel|^deactivate/.test(lower)) {
    fields.push(`  reason: z.string().min(1).optional(),`);
  } else if (/^connect|^sync|^integrate|^link/.test(lower)) {
    fields.push(`  source_system: z.string().min(1),`);
    fields.push(`  connection_config: z.record(z.unknown()),`);
  } else {
    fields.push(`  payload: z.record(z.unknown()),`);
  }

  // Add domain-specific fields based on context
  if (/supply.chain|procurement|inventory|warehouse/.test(ctxLower)) {
    fields.push(`  facility_id: z.string().min(1).optional(),`);
    fields.push(`  quantity: z.coerce.number().positive().optional(),`);
  }
  if (/carbon|emission|sustainability|esg/.test(ctxLower)) {
    fields.push(`  emission_factor: z.coerce.number().nonnegative().optional(),`);
    fields.push(`  reporting_period: z.string().datetime({ offset: true }).optional(),`);
  }
  if (/sap|erp|financial/.test(ctxLower)) {
    fields.push(`  company_code: z.string().min(1).optional(),`);
    fields.push(`  fiscal_year: z.coerce.number().int().optional(),`);
  }

  fields.push(`  correlation_id: z.string().uuid().optional(),`);
  return fields;
}

/**
 * Infer typed default query fields when the DDD model has no explicit parameters.
 */
function inferDefaultQueryFields(contextName: string): string[] {
  const ctxLower = contextName.toLowerCase();
  const fields: string[] = [
    `  status: z.enum(['active', 'inactive', 'pending', 'completed', 'error']).optional(),`,
    `  created_after: z.string().datetime({ offset: true }).optional(),`,
    `  created_before: z.string().datetime({ offset: true }).optional(),`,
    `  search: z.string().max(500).optional(),`,
  ];

  if (/supply.chain|procurement|inventory|warehouse/.test(ctxLower)) {
    fields.push(`  facility_id: z.string().optional(),`);
    fields.push(`  supplier_code: z.string().optional(),`);
  }
  if (/carbon|emission|sustainability|esg/.test(ctxLower)) {
    fields.push(`  scope: z.enum(['scope_1', 'scope_2', 'scope_3']).optional(),`);
    fields.push(`  reporting_period: z.string().optional(),`);
  }
  if (/sap|erp|financial/.test(ctxLower)) {
    fields.push(`  company_code: z.string().optional(),`);
  }

  return fields;
}

function tsSchemas(contexts: DDDContext[]): string {
  const lines: string[] = [
    GENERATED_HEADER_TS,
    `import { z } from 'zod';`,
    '',
  ];

  for (const ctx of contexts) {
    const ctxLabel = pascalCase(ctx.name);
    lines.push(`// === ${ctxLabel} Schemas ===`);
    lines.push('');

    // Command schemas (POST body) — fields are required by default
    for (const cmd of ctx.commands) {
      const schemaName = `${pascalCase(cmd.name)}Schema`;
      const fields = (cmd.input ?? []).length > 0
        ? (cmd.input ?? []).map(f => {
            const fieldName = snakeCase(f);
            return `  ${fieldName}: ${inferZodType(f, true)},`;
          })
        : inferDefaultCommandFields(cmd.name, ctx.name);
      lines.push(`export const ${schemaName} = z.object({`);
      lines.push(...fields);
      lines.push('});');
      lines.push(`export type ${pascalCase(cmd.name)}Input = z.infer<typeof ${schemaName}>;`);
      lines.push('');
    }

    // Query schemas (GET params) — fields are optional (query filters)
    for (const q of ctx.queries) {
      const schemaName = `${pascalCase(q.name)}Schema`;
      const fields = (q.parameters ?? []).length > 0
        ? (q.parameters ?? []).map(f => {
            const fieldName = snakeCase(f);
            return `  ${fieldName}: ${inferZodType(f, false)},`;
          })
        : inferDefaultQueryFields(ctx.name);
      lines.push(`export const ${schemaName} = z.object({`);
      lines.push(...fields);
      lines.push('  limit: z.coerce.number().int().positive().default(50),');
      lines.push('  offset: z.coerce.number().int().nonnegative().default(0),');
      lines.push('});');
      lines.push(`export type ${pascalCase(q.name)}Params = z.infer<typeof ${schemaName}>;`);
      lines.push('');
    }
  }

  return lines.join('\n');
}

/**
 * Generate the DI factory module dynamically from DDD bounded contexts.
 * One port interface + adapter per context, plus a shared AuditPort.
 */
function tsDependencies(contexts: DDDContext[], simulationContext: import('../types.js').SimulationContext | null): string {
  const lines: string[] = [
    GENERATED_HEADER_TS,
    `import { randomUUID } from 'node:crypto';`,
    `import type { DbClient, ErpClient } from '../infra/clients.js';`,
    `import { ConsoleTelemetry } from '../infra/telemetry.js';`,
    `import type { Telemetry } from '../infra/telemetry.js';`,
    '',
    '// ============================================================================',
    '// Audit Port (shared across all contexts)',
    '// ============================================================================',
    '',
    'export interface AuditEntry {',
    '  id: string;',
    '  entity_type: string;',
    '  entity_id: string;',
    '  action: string;',
    '  actor: string;',
    '  payload: unknown;',
    '  created_at: string;',
    '}',
    '',
    'export interface IAuditPort {',
    '  log(entityType: string, entityId: string, action: string, actor: string, payload: unknown): Promise<AuditEntry>;',
    '}',
    '',
    'class AuditAdapter implements IAuditPort {',
    '  constructor(private readonly db: DbClient) {}',
    '',
    '  async log(entityType: string, entityId: string, action: string, actor: string, payload: unknown): Promise<AuditEntry> {',
    '    const id = randomUUID();',
    '    const now = new Date().toISOString();',
    '    await this.db.execute(',
    '      \'INSERT INTO audit_log (id, entity_type, entity_id, action, actor, payload, created_at) VALUES (:1, :2, :3, :4, :5, :6, :7)\',',
    '      [id, entityType, entityId, action, actor, JSON.stringify(payload), now],',
    '    );',
    '    return { id, entity_type: entityType, entity_id: entityId, action, actor, payload, created_at: now };',
    '  }',
    '}',
    '',
    '// ============================================================================',
    '// Simulation Lineage (ADR-051)',
    '// ============================================================================',
    '',
    'import { createHash } from \'node:crypto\';',
    '',
    '/** Hash simulation inputs for immutability proof. */',
    'export function hashSimulationInputs(params: Record<string, unknown>): string {',
    '  const canonical = JSON.stringify(params, Object.keys(params).sort());',
    '  return createHash(\'sha256\').update(canonical).digest(\'hex\');',
    '}',
    '',
    'export interface SimulationLineage {',
    '  simulationRunId: string;',
    '  inputHash: string;',
    '  createdBy: string;',
    '  createdAt: string;',
    '}',
    '',
    '/** Validate that a decision traces to a valid, untampered simulation. */',
    'export async function validateLineage(',
    '  decisionId: string,',
    '  db: DbClient,',
    '): Promise<{ valid: boolean; reason?: string }> {',
    '  const decision = await db.query(',
    '    \'SELECT simulation_run_id, status FROM decisions WHERE id = :1\',',
    '    [decisionId],',
    '  );',
    '  if (!decision[0]) return { valid: false, reason: \'Decision not found\' };',
    '  const d = decision[0] as Record<string, unknown>;',
    '  if (d[\'status\'] !== \'approved\') return { valid: false, reason: `Decision status is ${d[\'status\']}, must be approved` };',
    '  if (!d[\'simulation_run_id\']) return { valid: false, reason: \'Decision has no simulation lineage\' };',
    '',
    '  const sim = await db.query(',
    '    \'SELECT input_hash, parameters FROM simulation_runs WHERE id = :1\',',
    '    [d[\'simulation_run_id\']],',
    '  );',
    '  if (!sim[0]) return { valid: false, reason: \'Linked simulation not found\' };',
    '  const s = sim[0] as Record<string, unknown>;',
    '  const currentHash = hashSimulationInputs(JSON.parse(s[\'parameters\'] as string));',
    '  if (currentHash !== s[\'input_hash\']) return { valid: false, reason: \'Simulation inputs tampered — hash mismatch\' };',
    '',
    '  return { valid: true };',
    '}',
    '',
  ];

  // ADR-052: Simulation port — provides access to RuVector simulation results and CostOps
  if (simulationContext && (simulationContext.scenarios.length > 0 || simulationContext.simulationId)) {
    lines.push('// ============================================================================');
    lines.push('// Simulation Port (ADR-052)');
    lines.push('// ============================================================================');
    lines.push('');
    lines.push('export interface SimulationScenario {');
    lines.push('  id: string;');
    lines.push('  name: string;');
    lines.push('  costDelta: number;');
    lines.push('  riskLevel: string;');
    lines.push('  mitigationStrategy: string;');
    lines.push('  reliability: number;');
    lines.push('}');
    lines.push('');
    lines.push('export interface CostModel {');
    lines.push('  baselineCost: number;');
    lines.push('  scenarioVariants: Array<{ scenarioId: string; costDelta: number; explanation: string }>;');
    lines.push('  budgetThreshold: number;');
    lines.push('  roi: number;');
    lines.push('  confidence: number;');
    lines.push('}');
    lines.push('');
    lines.push('export interface ISimulationPort {');
    lines.push('  getScenarios(): Promise<SimulationScenario[]>;');
    lines.push('  getScenarioById(id: string): Promise<SimulationScenario | null>;');
    lines.push('  compareScenarios(ids: string[]): Promise<{ scenarios: SimulationScenario[]; paretoFrontier: string[] }>;');
    lines.push('  getCostModel(): Promise<CostModel | null>;');
    lines.push('  getSimulationId(): string | null;');
    lines.push('}');
    lines.push('');
    lines.push('/** Embedded simulation adapter — reads from generated simulation-context.json */');
    lines.push('class EmbeddedSimulationAdapter implements ISimulationPort {');
    lines.push('  private readonly scenarios: SimulationScenario[];');
    lines.push('  private readonly costModel: CostModel | null;');
    lines.push('  private readonly simulationId: string | null;');
    lines.push('');
    lines.push('  constructor(contextPath: string) {');
    lines.push('    try {');
    lines.push("      const raw = JSON.parse(require('node:fs').readFileSync(contextPath, 'utf-8'));");
    lines.push('      this.scenarios = raw.scenarios ?? [];');
    lines.push('      this.costModel = raw.costModel ?? null;');
    lines.push('      this.simulationId = raw.simulationId ?? null;');
    lines.push('    } catch {');
    lines.push('      this.scenarios = [];');
    lines.push('      this.costModel = null;');
    lines.push('      this.simulationId = null;');
    lines.push('    }');
    lines.push('  }');
    lines.push('');
    lines.push('  async getScenarios(): Promise<SimulationScenario[]> { return this.scenarios; }');
    lines.push('  async getScenarioById(id: string): Promise<SimulationScenario | null> {');
    lines.push('    return this.scenarios.find(s => s.id === id) ?? null;');
    lines.push('  }');
    lines.push('  async compareScenarios(ids: string[]): Promise<{ scenarios: SimulationScenario[]; paretoFrontier: string[] }> {');
    lines.push('    const selected = this.scenarios.filter(s => ids.includes(s.id));');
    lines.push('    // Simple Pareto: non-dominated on (cost, reliability)');
    lines.push('    const pareto = selected.filter(a =>');
    lines.push('      !selected.some(b => b.costDelta <= a.costDelta && b.reliability >= a.reliability && (b.costDelta < a.costDelta || b.reliability > a.reliability))');
    lines.push('    );');
    lines.push('    return { scenarios: selected, paretoFrontier: pareto.map(p => p.id) };');
    lines.push('  }');
    lines.push('  async getCostModel(): Promise<CostModel | null> { return this.costModel; }');
    lines.push('  getSimulationId(): string | null { return this.simulationId; }');
    lines.push('}');
    lines.push('');
  }

  // Per-context port interfaces and adapters
  for (const ctx of contexts) {
    const ctxPascal = pascalCase(ctx.name);
    const ctxSnake = snakeCase(ctx.name);
    const tableName = `${ctxSnake}_records`;

    lines.push(`// === ${ctxPascal} Port ===`);
    // Document domain invariants as comments (ADR-048)
    if (ctx.invariants.length > 0) {
      lines.push(`// Domain Invariants:`);
      for (const inv of ctx.invariants.slice(0, 8)) {
        lines.push(`//   - ${inv.slice(0, 120)}`);
      }
    }
    if (ctx.domainEvents.length > 0) {
      lines.push(`// Domain Events: ${ctx.domainEvents.map(e => e.name).join(', ')}`);
    }
    lines.push('');
    lines.push(`export interface ${ctxPascal}Record {`);
    lines.push('  id: string;');
    lines.push('  status: string;');
    lines.push('  created_at: string;');
    lines.push('  updated_at: string;');
    lines.push('  data: Record<string, unknown>;');
    lines.push('}');
    lines.push('');
    lines.push(`export interface I${ctxPascal}Port {`);
    lines.push(`  execute(command: string, payload: Record<string, unknown>): Promise<${ctxPascal}Record>;`);
    lines.push(`  query(filters: Record<string, unknown>, limit: number, offset: number): Promise<{ rows: ${ctxPascal}Record[]; total: number }>;`);
    lines.push(`  getById(id: string): Promise<${ctxPascal}Record | null>;`);
    lines.push('}');
    lines.push('');
    lines.push(`class ${ctxPascal}Adapter implements I${ctxPascal}Port {`);
    lines.push('  constructor(private readonly db: DbClient, private readonly telemetry: Telemetry) {}');
    lines.push('');

    // ── ADR-048: Generate domain-specific execute() with precondition guards ──
    lines.push(`  async execute(command: string, payload: Record<string, unknown>): Promise<${ctxPascal}Record> {`);

    if (ctx.commands.length > 0) {
      // Generate a switch on command name with precondition checks per command
      lines.push(`    return this.telemetry.withSpan('${ctxSnake}', command, {}, async () => {`);
      lines.push('      const id = randomUUID();');
      lines.push('      const now = new Date().toISOString();');
      lines.push('');
      lines.push('      // Domain command dispatch with precondition enforcement');
      lines.push('      switch (command) {');

      for (const cmd of ctx.commands) {
        const cmdName = cmd.name;
        lines.push(`        case '${cmdName}': {`);

        // Precondition guards (ADR-048: enforce business rules)
        if (cmd.preconditions && cmd.preconditions.length > 0) {
          lines.push(`          // Preconditions: ${cmd.description ?? cmdName}`);
          for (const pre of cmd.preconditions) {
            // Generate a runtime validation comment + guard
            const safePre = pre.replace(/'/g, "\\'").slice(0, 120);
            lines.push(`          // RULE: ${safePre}`);
          }
          lines.push(`          // TODO: Implement precondition enforcement for ${cmdName}`);
          lines.push(`          // Preconditions from domain model: ${cmd.preconditions.map(p => p.slice(0, 60)).join('; ')}`);
        }

        // Input field validation (if input fields are defined)
        if (cmd.input && cmd.input.length > 0) {
          const inputFields = cmd.input.filter(f => typeof f === 'string' && f.length > 0);
          if (inputFields.length > 0) {
            lines.push(`          // Required input fields: ${inputFields.join(', ')}`);
            for (const field of inputFields.slice(0, 8)) {
              const safeField = field.replace(/[^a-zA-Z0-9_]/g, '_');
              lines.push(`          if (payload['${safeField}'] === undefined) throw new Error('${cmdName}: missing required field "${safeField}"');`);
            }
          }
        }

        lines.push('          break;');
        lines.push('        }');
      }

      lines.push('        default:');
      lines.push(`          // Unknown command — accept but log warning`);
      lines.push(`          console.warn(JSON.stringify({ level: 'warn', context: '${ctxSnake}', message: \`Unknown command: \${command}\` }));`);
      lines.push('          break;');
      lines.push('      }');
      lines.push('');

      // Insert with command name stored (not just generic 'active')
      lines.push('      await this.db.execute(');
      lines.push(`        'INSERT INTO ${tableName} (id, status, created_at, updated_at, data) VALUES (:1, :2, :3, :4, :5)',`);
      lines.push("        [id, command, now, now, JSON.stringify(payload)],");
      lines.push('      );');

      // Domain event emission (ADR-048: cross-context communication)
      const relevantEvents = ctx.domainEvents.filter(e => ctx.commands.some(c => e.triggeredBy === c.name || e.triggeredBy === ''));
      if (relevantEvents.length > 0 || ctx.domainEvents.length > 0) {
        lines.push('');
        lines.push('      // Emit domain event for cross-context communication');
        lines.push(`      console.log(JSON.stringify({`);
        lines.push(`        type: 'DOMAIN_EVENT',`);
        lines.push(`        context: '${ctxSnake}',`);
        lines.push(`        event: \`\${command}_completed\`,`);
        lines.push('        aggregateId: id,');
        lines.push('        payload,');
        lines.push('        timestamp: now,');
        lines.push('      }));');
      }

      lines.push('');
      lines.push(`      return { id, status: command, created_at: now, updated_at: now, data: payload };`);
      lines.push('    });');
    } else {
      // Fallback for contexts with no defined commands
      lines.push(`    return this.telemetry.withSpan('${ctxSnake}', command, {}, async () => {`);
      lines.push('      const id = randomUUID();');
      lines.push('      const now = new Date().toISOString();');
      lines.push('      await this.db.execute(');
      lines.push(`        'INSERT INTO ${tableName} (id, status, created_at, updated_at, data) VALUES (:1, :2, :3, :4, :5)',`);
      lines.push("        [id, command, now, now, JSON.stringify(payload)],");
      lines.push('      );');
      lines.push(`      return { id, status: command, created_at: now, updated_at: now, data: payload };`);
      lines.push('    });');
    }

    lines.push('  }');
    lines.push('');
    lines.push(`  async query(filters: Record<string, unknown>, limit: number, offset: number): Promise<{ rows: ${ctxPascal}Record[]; total: number }> {`);
    lines.push(`    return this.telemetry.withSpan('${ctxSnake}', 'query', {}, async () => {`);
    // ADR-056: Column allowlist per entity — only known columns can be filtered
    lines.push(`      const FILTERABLE_COLUMNS = new Set(['id', 'status', 'created_at', 'updated_at']);`);
    lines.push('      const whereClauses: string[] = [];');
    lines.push('      const params: unknown[] = [];');
    lines.push('      let paramIdx = 1;');
    lines.push('      for (const [key, value] of Object.entries(filters)) {');
    lines.push('        if (value !== undefined && value !== null && FILTERABLE_COLUMNS.has(key)) {');
    lines.push('          whereClauses.push(`${key} = :${paramIdx}`);');
    lines.push('          params.push(value);');
    lines.push('          paramIdx++;');
    lines.push('        }');
    lines.push('      }');
    lines.push('      const whereSQL = whereClauses.length > 0 ? `WHERE ${whereClauses.join(\' AND \')}` : \'\';');
    lines.push('');
    lines.push(`      const countRows = await this.db.query(\`SELECT COUNT(*) as cnt FROM ${tableName} \${whereSQL}\`, params);`);
    lines.push("      const total = (countRows[0] as Record<string, number>)?.cnt ?? 0;");
    lines.push('');
    lines.push('      // LIMIT and OFFSET are parameterized — never interpolated into SQL');
    lines.push('      const paginatedParams = [...params, limit, offset];');
    lines.push(`      const dataRows = await this.db.query(`);
    lines.push(`        \`SELECT * FROM ${tableName} \${whereSQL} ORDER BY created_at DESC LIMIT :\${paramIdx} OFFSET :\${paramIdx + 1}\`,`);
    lines.push('        paginatedParams,');
    lines.push('      );');
    lines.push(`      return { rows: dataRows as unknown as ${ctxPascal}Record[], total };`);
    lines.push('    });');
    lines.push('  }');
    lines.push('');
    lines.push(`  async getById(id: string): Promise<${ctxPascal}Record | null> {`);
    lines.push(`    const rows = await this.db.query('SELECT * FROM ${tableName} WHERE id = :1', [id]);`);
    lines.push(`    return (rows[0] as ${ctxPascal}Record) ?? null;`);
    lines.push('  }');
    lines.push('}');
    lines.push('');
  }

  // ADR-054: Decision Port — human-in-the-loop approval workflow
  lines.push('// ============================================================================');
  lines.push('// Decision Port (ADR-054) — approval workflow with state machine');
  lines.push('// ============================================================================');
  lines.push('');
  lines.push("export type DecisionStatus = 'draft' | 'submitted' | 'approved' | 'rejected' | 'executed';");
  lines.push('');
  lines.push('const VALID_TRANSITIONS: Record<DecisionStatus, DecisionStatus[]> = {');
  lines.push("  draft: ['submitted'],");
  lines.push("  submitted: ['approved', 'rejected'],");
  lines.push("  approved: ['executed'],");
  lines.push("  rejected: ['draft'],");
  lines.push('  executed: [],');
  lines.push('};');
  lines.push('');
  lines.push('export interface DecisionRecord {');
  lines.push('  id: string;');
  lines.push('  simulationRunId: string;');
  lines.push('  strategyId: string;');
  lines.push('  recommendedAction: string;');
  lines.push('  justification: string;');
  lines.push('  status: DecisionStatus;');
  lines.push('  submittedBy: string;');
  lines.push('  approvedBy: string | null;');
  lines.push('  rejectedBy: string | null;');
  lines.push('  rejectionReason: string | null;');
  lines.push('  executedBy: string | null;');
  lines.push('  createdAt: string;');
  lines.push('  updatedAt: string;');
  lines.push('}');
  lines.push('');
  lines.push('export interface IDecisionPort {');
  lines.push('  submit(simulationRunId: string, strategyId: string, recommendedAction: string, justification: string, submittedBy: string): Promise<DecisionRecord>;');
  lines.push('  approve(id: string, approvedBy: string): Promise<DecisionRecord>;');
  lines.push('  reject(id: string, rejectedBy: string, reason: string): Promise<DecisionRecord>;');
  lines.push('  execute(id: string, executedBy: string): Promise<DecisionRecord>;');
  lines.push('  getById(id: string): Promise<DecisionRecord | null>;');
  lines.push('  listByStatus(status: DecisionStatus): Promise<DecisionRecord[]>;');
  lines.push('}');
  lines.push('');
  lines.push('class DecisionAdapter implements IDecisionPort {');
  lines.push('  constructor(private readonly db: DbClient, private readonly telemetry: Telemetry) {}');
  lines.push('');
  lines.push('  private assertTransition(current: DecisionStatus, target: DecisionStatus): void {');
  lines.push('    if (!VALID_TRANSITIONS[current]?.includes(target)) {');
  lines.push('      throw new Error(`Invalid transition: ${current} → ${target}. Allowed: ${VALID_TRANSITIONS[current]?.join(", ") ?? "none"}`);');
  lines.push('    }');
  lines.push('  }');
  lines.push('');
  lines.push("  async submit(simulationRunId: string, strategyId: string, recommendedAction: string, justification: string, submittedBy: string): Promise<DecisionRecord> {");
  lines.push("    return this.telemetry.withSpan('decisions', 'submit', {}, async () => {");
  lines.push('      const id = randomUUID();');
  lines.push('      const now = new Date().toISOString();');
  lines.push("      const record: DecisionRecord = { id, simulationRunId, strategyId, recommendedAction, justification, status: 'submitted', submittedBy, approvedBy: null, rejectedBy: null, rejectionReason: null, executedBy: null, createdAt: now, updatedAt: now };");
  lines.push('      await this.db.execute(');
  lines.push("        'INSERT INTO decisions (id, simulation_run_id, strategy_id, recommended_action, justification, status, submitted_by, created_at, updated_at) VALUES (:1, :2, :3, :4, :5, :6, :7, :8, :9)',");
  lines.push("        [id, simulationRunId, strategyId, recommendedAction, justification, 'submitted', submittedBy, now, now],");
  lines.push('      );');
  lines.push('      return record;');
  lines.push('    });');
  lines.push('  }');
  lines.push('');
  lines.push('  async approve(id: string, approvedBy: string): Promise<DecisionRecord> {');
  lines.push("    return this.telemetry.withSpan('decisions', 'approve', {}, async () => {");
  lines.push('      const current = await this.getById(id);');
  lines.push("      if (!current) throw new Error('Decision not found');");
  lines.push("      this.assertTransition(current.status, 'approved');");
  lines.push('      if (approvedBy === current.submittedBy) throw new Error(\'Self-approval is not allowed\');');
  lines.push('      const now = new Date().toISOString();');
  lines.push('      await this.db.execute(');
  lines.push("        'UPDATE decisions SET status = :1, approved_by = :2, updated_at = :3 WHERE id = :4',");
  lines.push("        ['approved', approvedBy, now, id],");
  lines.push('      );');
  lines.push("      return { ...current, status: 'approved' as const, approvedBy, updatedAt: now };");
  lines.push('    });');
  lines.push('  }');
  lines.push('');
  lines.push('  async reject(id: string, rejectedBy: string, reason: string): Promise<DecisionRecord> {');
  lines.push("    return this.telemetry.withSpan('decisions', 'reject', {}, async () => {");
  lines.push('      const current = await this.getById(id);');
  lines.push("      if (!current) throw new Error('Decision not found');");
  lines.push("      this.assertTransition(current.status, 'rejected');");
  lines.push('      const now = new Date().toISOString();');
  lines.push('      await this.db.execute(');
  lines.push("        'UPDATE decisions SET status = :1, rejected_by = :2, rejection_reason = :3, updated_at = :4 WHERE id = :5',");
  lines.push("        ['rejected', rejectedBy, reason, now, id],");
  lines.push('      );');
  lines.push("      return { ...current, status: 'rejected' as const, rejectedBy, rejectionReason: reason, updatedAt: now };");
  lines.push('    });');
  lines.push('  }');
  lines.push('');
  lines.push('  async execute(id: string, executedBy: string): Promise<DecisionRecord> {');
  lines.push("    return this.telemetry.withSpan('decisions', 'execute', {}, async () => {");
  lines.push('      const current = await this.getById(id);');
  lines.push("      if (!current) throw new Error('Decision not found');");
  lines.push("      this.assertTransition(current.status, 'executed');");
  lines.push('      const now = new Date().toISOString();');
  lines.push('      await this.db.execute(');
  lines.push("        'UPDATE decisions SET status = :1, executed_by = :2, updated_at = :3 WHERE id = :4',");
  lines.push("        ['executed', executedBy, now, id],");
  lines.push('      );');
  lines.push("      return { ...current, status: 'executed' as const, executedBy, updatedAt: now };");
  lines.push('    });');
  lines.push('  }');
  lines.push('');
  lines.push('  async getById(id: string): Promise<DecisionRecord | null> {');
  lines.push("    const rows = await this.db.query('SELECT * FROM decisions WHERE id = :1', [id]);");
  lines.push('    if (!rows[0]) return null;');
  lines.push('    const r = rows[0] as Record<string, unknown>;');
  lines.push('    return {');
  lines.push("      id: String(r['id']),");
  lines.push("      simulationRunId: String(r['simulation_run_id'] ?? ''),");
  lines.push("      strategyId: String(r['strategy_id'] ?? ''),");
  lines.push("      recommendedAction: String(r['recommended_action'] ?? ''),");
  lines.push("      justification: String(r['justification'] ?? ''),");
  lines.push("      status: String(r['status']) as DecisionStatus,");
  lines.push("      submittedBy: String(r['submitted_by'] ?? ''),");
  lines.push("      approvedBy: r['approved_by'] ? String(r['approved_by']) : null,");
  lines.push("      rejectedBy: r['rejected_by'] ? String(r['rejected_by']) : null,");
  lines.push("      rejectionReason: r['rejection_reason'] ? String(r['rejection_reason']) : null,");
  lines.push("      executedBy: r['executed_by'] ? String(r['executed_by']) : null,");
  lines.push("      createdAt: String(r['created_at']),");
  lines.push("      updatedAt: String(r['updated_at']),");
  lines.push('    };');
  lines.push('  }');
  lines.push('');
  lines.push('  async listByStatus(status: DecisionStatus): Promise<DecisionRecord[]> {');
  lines.push("    const rows = await this.db.query('SELECT * FROM decisions WHERE status = :1 ORDER BY updated_at DESC', [status]);");
  lines.push('    return rows.map(r => {');
  lines.push('      const row = r as Record<string, unknown>;');
  lines.push('      return {');
  lines.push("        id: String(row['id']),");
  lines.push("        simulationRunId: String(row['simulation_run_id'] ?? ''),");
  lines.push("        strategyId: String(row['strategy_id'] ?? ''),");
  lines.push("        recommendedAction: String(row['recommended_action'] ?? ''),");
  lines.push("        justification: String(row['justification'] ?? ''),");
  lines.push("        status: String(row['status']) as DecisionStatus,");
  lines.push("        submittedBy: String(row['submitted_by'] ?? ''),");
  lines.push("        approvedBy: row['approved_by'] ? String(row['approved_by']) : null,");
  lines.push("        rejectedBy: row['rejected_by'] ? String(row['rejected_by']) : null,");
  lines.push("        rejectionReason: row['rejection_reason'] ? String(row['rejection_reason']) : null,");
  lines.push("        executedBy: row['executed_by'] ? String(row['executed_by']) : null,");
  lines.push("        createdAt: String(row['created_at']),");
  lines.push("        updatedAt: String(row['updated_at']),");
  lines.push('      };');
  lines.push('    });');
  lines.push('  }');
  lines.push('}');
  lines.push('');

  // Dependencies interface
  lines.push('// ============================================================================');
  lines.push('// Dependency Container');
  lines.push('// ============================================================================');
  lines.push('');
  lines.push('export interface Dependencies {');
  for (const ctx of contexts) {
    lines.push(`  readonly ${camelCase(ctx.name)}: I${pascalCase(ctx.name)}Port;`);
  }
  lines.push('  readonly audit: IAuditPort;');
  lines.push('  readonly decisions: IDecisionPort;');
  lines.push('  readonly erp: ErpClient;');
  if (simulationContext && (simulationContext.scenarios.length > 0 || simulationContext.simulationId)) {
    lines.push('  readonly simulation: ISimulationPort;');
  }
  lines.push('}');
  lines.push('');

  // Factory
  lines.push('export function createDependencies(db: DbClient, erp: ErpClient): Dependencies {');
  lines.push('  const telemetry: Telemetry = new ConsoleTelemetry();');
  lines.push('  return {');
  for (const ctx of contexts) {
    lines.push(`    ${camelCase(ctx.name)}: new ${pascalCase(ctx.name)}Adapter(db, telemetry),`);
  }
  lines.push('    audit: new AuditAdapter(db),');
  lines.push('    decisions: new DecisionAdapter(db, telemetry),');
  lines.push('    erp,');
  if (simulationContext && (simulationContext.scenarios.length > 0 || simulationContext.simulationId)) {
    lines.push("    simulation: new EmbeddedSimulationAdapter(require('node:path').join(__dirname, '..', 'data', 'simulation-context.json')),");
  }
  lines.push('  };');
  lines.push('}');
  lines.push('');

  return lines.join('\n');
}

/**
 * Generate TypeScript routes.ts with real domain logic wired through port adapters.
 * Each handler validates with Zod, delegates to the appropriate adapter, emits
 * audit events, and returns proper HTTP status codes.
 */
/** Map ERP system to client class name and env var prefix. */
function resolveErpClientMeta(erpSystem: string): { className: string; envPrefix: string; baseUrlDefault: string } {
  const n = erpSystem.toLowerCase();
  if (n.includes('netsuite'))   return { className: 'NetSuiteClient',  envPrefix: 'NETSUITE',  baseUrlDefault: 'https://netsuite.example.com' };
  if (n.includes('sap'))        return { className: 'SAPClient',       envPrefix: 'SAP',       baseUrlDefault: 'https://sap.example.com' };
  if (n.includes('dynamics'))   return { className: 'DynamicsClient',  envPrefix: 'DYNAMICS',  baseUrlDefault: 'https://dynamics.example.com' };
  if (n.includes('deltek') || n.includes('costpoint')) return { className: 'DeltekClient', envPrefix: 'DELTEK', baseUrlDefault: 'https://costpoint.example.com' };
  if (n.includes('guidewire'))  return { className: 'GuidewireClient', envPrefix: 'GUIDEWIRE', baseUrlDefault: 'https://guidewire.example.com' };
  if (n.includes('epicor'))     return { className: 'EpicorClient',    envPrefix: 'EPICOR',    baseUrlDefault: 'https://epicor.example.com' };
  if (n.includes('infor'))      return { className: 'InforClient',     envPrefix: 'INFOR',     baseUrlDefault: 'https://infor.example.com' };
  if (n.includes('workday'))    return { className: 'WorkdayClient',   envPrefix: 'WORKDAY',   baseUrlDefault: 'https://workday.example.com' };
  if (n.includes('ifs'))        return { className: 'IFSClient',       envPrefix: 'IFS',       baseUrlDefault: 'https://ifs.example.com' };
  if (n.includes('sage') || n.includes('intacct')) return { className: 'SageClient', envPrefix: 'SAGE', baseUrlDefault: 'https://intacct.example.com' };
  if (n.includes('oracle'))     return { className: 'OracleERPClient', envPrefix: 'ORACLE_ERP', baseUrlDefault: 'https://oracle-erp.example.com' };
  return { className: 'ERPClient', envPrefix: 'ERP', baseUrlDefault: 'https://erp.example.com' };
}

function tsRoutes(erpSystem: string, contexts: DDDContext[], simulationContext: import('../types.js').SimulationContext | null): { content: string; routeCount: number } {
  const erpMeta = resolveErpClientMeta(erpSystem);

  // Collect all schema import names from contexts
  const schemaImports: string[] = [];
  for (const ctx of contexts) {
    for (const cmd of ctx.commands) {
      schemaImports.push(`${pascalCase(cmd.name)}Schema`);
    }
    for (const query of ctx.queries) {
      schemaImports.push(`${pascalCase(query.name)}Schema`);
    }
  }

  const lines: string[] = [
    GENERATED_HEADER_TS,
    `import { Hono } from 'hono';`,
    `import * as crypto from 'node:crypto';`,
    `import { correlationMiddleware, iamMiddleware, loggingMiddleware } from './middleware.js';`,
    `import { healthRouter } from './health.js';`,
    `import { createDependencies } from './dependencies.js';`,
    `import type { Dependencies } from './dependencies.js';`,
    `import type { DbClient, ErpClient } from '../infra/clients.js';`,
    `import { ${erpMeta.className} } from '../erp-client/client.js';`,
    `import type { GovernanceConfig } from '../erp-client/types.js';`,
    schemaImports.length > 0
      ? `import {\n${schemaImports.map(s => `  ${s},`).join('\n')}\n} from './schemas.js';`
      : `// No schemas generated`,
    '',
    '// ============================================================================',
    '// Error Response Helpers',
    '// ============================================================================',
    '',
    'interface ApiError {',
    '  readonly error: {',
    '    readonly code: string;',
    '    readonly message: string;',
    '    readonly details?: unknown;',
    '  };',
    '  readonly correlationId: string;',
    '}',
    '',
    'function validationError(correlationId: string, issues: unknown): ApiError {',
    '  return { error: { code: \'VALIDATION_ERROR\', message: \'Request validation failed\', details: issues }, correlationId };',
    '}',
    '',
    'function serverError(correlationId: string, message: string): ApiError {',
    '  return { error: { code: \'INTERNAL_ERROR\', message }, correlationId };',
    '}',
    '',
    'function forbiddenError(correlationId: string, requiredRoles: string[]): ApiError {',
    '  return { error: { code: \'FORBIDDEN\', message: `Requires role: ${requiredRoles.join(" | ")}` }, correlationId };',
    '}',
    '',
    '// ============================================================================',
    '// RBAC Middleware (ADR-049)',
    '// ============================================================================',
    '',
    'function requireRole(...roles: string[]) {',
    '  return createMiddleware(async (c, next) => {',
    '    const correlationId = c.get(\'correlationId\') as string ?? \'unknown\';',
    '    const claims = c.get(\'iamClaims\') as Record<string, unknown> | undefined;',
    '    if (!claims) {',
    '      return c.json({ error: { code: \'UNAUTHORIZED\', message: \'No claims available\' }, correlationId }, 401);',
    '    }',
    '',
    '    // Extract roles from standard JWT claims locations',
    '    const userRoles: string[] = (',
    '      Array.isArray(claims[\'roles\']) ? claims[\'roles\'] :',
    '      Array.isArray(claims[\'custom:roles\']) ? claims[\'custom:roles\'] :',
    '      Array.isArray(claims[\'realm_access\']?.[\'roles\']) ? (claims[\'realm_access\'] as Record<string, unknown>)[\'roles\'] :',
    '      typeof claims[\'scope\'] === \'string\' ? claims[\'scope\'].split(\' \') :',
    '      []',
    '    ) as string[];',
    '',
    '    const hasRole = roles.some(r => userRoles.includes(r));',
    '    if (!hasRole) {',
    '      console.warn(JSON.stringify({',
    '        level: \'warn\',',
    '        type: \'ACCESS_DENIED\',',
    '        correlationId,',
    '        actor: claims[\'sub\'] ?? \'unknown\',',
    '        requiredRoles: roles,',
    '        actualRoles: userRoles,',
    '        path: c.req.path,',
    '      }));',
    '      return c.json(forbiddenError(correlationId, roles), 403);',
    '    }',
    '',
    '    await next();',
    '  });',
    '}',
    '',
    '// ============================================================================',
    '// DI Bootstrap',
    '// ============================================================================',
    '',
    '// ADR-056: No-op clients for startup — replace with real DB/ERP in production',
    '// When DATABASE_URL is set, wire a real PostgreSQL client here.',
    '// When ERP_BASE_URL is set, wire the real ERP client here.',
    'if (!process.env.DATABASE_URL) {',
    "  console.warn(JSON.stringify({ level: 'warn', message: 'DATABASE_URL not set — using in-memory stub. Set DATABASE_URL for real database.' }));",
    '}',
    'const dbClient: DbClient = {',
    '  async query(sql: string, params: unknown[]): Promise<unknown[]> {',
    '    void sql; void params;',
    "    if (!process.env.DATABASE_URL) return [];",
    "    throw new Error('Real database client not yet wired — set DATABASE_URL and implement pg client');",
    '  },',
    '  async execute(sql: string, params: unknown[]): Promise<void> {',
    '    void sql; void params;',
    "    if (!process.env.DATABASE_URL) return;",
    "    throw new Error('Real database client not yet wired — set DATABASE_URL and implement pg client');",
    '  },',
    '};',
    '',
    'const erpClient: ErpClient = {',
    '  async invoke(operation: string, data: unknown): Promise<unknown> {',
    '    void operation; void data;',
    "    if (!process.env.ERP_BASE_URL) return {};",
    "    throw new Error('Real ERP client not yet wired — set ERP_BASE_URL and implement integration');",
    '  },',
    '};',
    '',
    'const deps: Dependencies = createDependencies(dbClient, erpClient);',
    '',
    `// ${erpMeta.className} ACL client with governance enforcement`,
    'const governanceConfig: GovernanceConfig = {',
    '  read_only: (process.env.ERP_READ_ONLY ?? \'true\') === \'true\',',
    '  audit_enabled: true,',
    '  pii_redaction: true,',
    '  max_tokens_per_request: 4096,',
    '};',
    '',
    `const erpClientInstance = new ${erpMeta.className}({`,
    `  baseUrl: process.env.${erpMeta.envPrefix}_BASE_URL ?? '${erpMeta.baseUrlDefault}',`,
    `  serviceAccountEmail: process.env.${erpMeta.envPrefix}_SA_EMAIL ?? '${erpMeta.envPrefix.toLowerCase()}-sa@project.iam.gserviceaccount.com',`,
    '  governance: governanceConfig,',
    '  audit: {',
    '    async log(entityType, entityId, action, actor, payload) {',
    '      await deps.audit.log(entityType, entityId, action, actor, payload);',
    '    },',
    '  },',
    '});',
    '',
    '// ============================================================================',
    '// App & Middleware',
    '// ============================================================================',
    '',
    'const app = new Hono();',
    '',
    'app.use(\'*\', correlationMiddleware);',
    'app.use(\'*\', iamMiddleware);',
    'app.use(\'*\', loggingMiddleware);',
    '',
    'app.route(\'/health\', healthRouter);',
    '',
  ];

  let routeCount = 0;

  // Generate one POST per command, one GET per query, grouped by bounded context
  for (const ctx of contexts) {
    const ctxSlug = slugify(ctx.name.replace(/Context$/i, ''));
    const ctxPascal = pascalCase(ctx.name.replace(/Context$/i, ''));

    lines.push(
      `// ============================================================================`,
      `// Bounded Context: ${ctxPascal}`,
      `// ============================================================================`,
      '',
    );

    // POST handlers for commands
    for (const cmd of ctx.commands) {
      const cmdSlug = slugify(cmd.name);
      const schemaName = `${pascalCase(cmd.name)}Schema`;
      const portName = `${camelCase(ctx.name.replace(/Context$/i, ''))}Port`;

      // ADR-049: Determine required role from command semantics
      const isApproval = /^(?:approve|reject|review|authorize)/i.test(cmd.name);
      const isErpWrite = /^(?:sync|push|write|export).*(?:erp|oracle|sap|workday)/i.test(cmd.name);
      const requiredRole = isApproval ? "'approver', 'admin'" : isErpWrite ? "'erp_writer', 'admin'" : "'writer', 'admin'";

      lines.push(
        `app.post('/api/v1/${ctxSlug}/${cmdSlug}', requireRole(${requiredRole}), async (c) => {`,
        '  const correlationId = c.get(\'correlationId\') as string;',
        '  const actor = ((c.get(\'iamClaims\') as Record<string, unknown>) ?? {})[\'sub\'] as string ?? \'unknown\';',
        '  const startTime = Date.now();',
        '  try {',
        '    const body = await c.req.json();',
        `    const parsed = ${schemaName}.safeParse(body);`,
        '    if (!parsed.success) {',
        '      return c.json(validationError(correlationId, parsed.error.issues), 400);',
        '    }',
        `    const result = await deps.${portName}.execute('${cmd.name}', parsed.data);`,
        `    await deps.audit.log('${ctxSlug}', result?.id ?? correlationId, '${cmdSlug}', actor, parsed.data);`,
        '    return c.json({',
        '      correlationId,',
        '      status: \'completed\',',
        '      data: result,',
        '      metadata: { response_time_ms: Date.now() - startTime },',
        '    }, 201);',
        '  } catch (err) {',
        '    console.error(JSON.stringify({ level: \'error\', correlationId, error: err instanceof Error ? err.message : String(err), stack: err instanceof Error ? err.stack : undefined, path: c.req.path }));',
        `    await deps.audit.log('${ctxSlug}', correlationId, '${cmdSlug}:failed', actor, { error: err instanceof Error ? err.message : String(err) });`,
        '    const message = process.env.NODE_ENV === \'production\' ? \'Internal server error\' : (err instanceof Error ? err.message : \'Unknown error\');',
        '    return c.json(serverError(correlationId, message), 500);',
        '  }',
        '});',
        '',
      );
      routeCount++;
    }

    // GET handlers for queries
    for (const query of ctx.queries) {
      const querySlug = slugify(query.name);
      const schemaName = `${pascalCase(query.name)}Schema`;
      const portName = `${camelCase(ctx.name.replace(/Context$/i, ''))}Port`;

      lines.push(
        `app.get('/api/v1/${ctxSlug}/${querySlug}', requireRole('viewer', 'writer', 'admin'), async (c) => {`,
        '  const correlationId = c.get(\'correlationId\') as string;',
        '  const actor = ((c.get(\'iamClaims\') as Record<string, unknown>) ?? {})[\'sub\'] as string ?? \'unknown\';',
        '  const startTime = Date.now();',
        '  try {',
        '    const params = c.req.query();',
        `    const parsed = ${schemaName}.safeParse(params);`,
        '    if (!parsed.success) {',
        '      return c.json(validationError(correlationId, parsed.error.issues), 400);',
        '    }',
        `    const result = await deps.${portName}.query('${query.name}', parsed.data);`,
        `    await deps.audit.log('${ctxSlug}', correlationId, '${querySlug}:read', actor, { resultCount: result.total });`,
        '    return c.json({',
        '      correlationId,',
        '      status: \'ok\',',
        '      data: result.rows,',
        '      pagination: { limit: parsed.data.limit ?? 50, offset: parsed.data.offset ?? 0, total: result.total },',
        '      metadata: { response_time_ms: Date.now() - startTime },',
        '    }, 200);',
        '  } catch (err) {',
        '    console.error(JSON.stringify({ level: \'error\', correlationId, error: err instanceof Error ? err.message : String(err), stack: err instanceof Error ? err.stack : undefined, path: c.req.path }));',
        '    const message = process.env.NODE_ENV === \'production\' ? \'Internal server error\' : (err instanceof Error ? err.message : \'Unknown error\');',
        '    return c.json(serverError(correlationId, message), 500);',
        '  }',
        '});',
        '',
      );
      routeCount++;
    }
  }

  // ADR-054: Decision approval workflow endpoints (always generated)
  lines.push(
    '// ============================================================================',
    '// Decision Approval Workflow (ADR-054) — human-in-the-loop governance',
    '// ============================================================================',
    '',
    "app.post('/api/v1/decisions', requireRole('writer', 'analyst', 'admin'), async (c) => {",
    '  const correlationId = c.get(\'correlationId\') as string;',
    '  const actor = ((c.get(\'iamClaims\') as Record<string, unknown>) ?? {})[\'sub\'] as string ?? \'unknown\';',
    '  try {',
    '    const body = await c.req.json();',
    '    const { simulationRunId, strategyId, recommendedAction, justification } = body as Record<string, string>;',
    '    if (!simulationRunId || !strategyId || !recommendedAction || !justification) {',
    '      return c.json(validationError(correlationId, [{ message: \'Required: simulationRunId, strategyId, recommendedAction, justification\' }]), 400);',
    '    }',
    '    const result = await deps.decisions.submit(simulationRunId, strategyId, recommendedAction, justification, actor);',
    '    await deps.audit.log(\'decisions\', result.id, \'submitted\', actor, { simulationRunId, strategyId });',
    '    return c.json({ correlationId, status: \'created\', data: result }, 201);',
    '  } catch (err) {',
    '    console.error(JSON.stringify({ level: \'error\', correlationId, error: err instanceof Error ? err.message : String(err), path: c.req.path }));',
    '    const message = process.env.NODE_ENV === \'production\' ? \'Internal server error\' : (err instanceof Error ? err.message : \'Unknown error\');',
    '    return c.json(serverError(correlationId, message), 500);',
    '  }',
    '});',
    '',
    "app.post('/api/v1/decisions/:id/approve', requireRole('approver', 'admin'), async (c) => {",
    '  const correlationId = c.get(\'correlationId\') as string;',
    '  const actor = ((c.get(\'iamClaims\') as Record<string, unknown>) ?? {})[\'sub\'] as string ?? \'unknown\';',
    '  const id = c.req.param(\'id\');',
    '  try {',
    '    const result = await deps.decisions.approve(id, actor);',
    '    await deps.audit.log(\'decisions\', id, \'approved\', actor, { approvedBy: actor });',
    '    return c.json({ correlationId, status: \'approved\', data: result }, 200);',
    '  } catch (err) {',
    '    console.error(JSON.stringify({ level: \'error\', correlationId, error: err instanceof Error ? err.message : String(err), path: c.req.path }));',
    '    await deps.audit.log(\'decisions\', id, \'approve:failed\', actor, { error: err instanceof Error ? err.message : String(err) });',
    '    const message = err instanceof Error ? err.message : \'Unknown error\';',
    '    const status = message.includes(\'not found\') ? 404 : message.includes(\'transition\') || message.includes(\'Self-approval\') ? 422 : 500;',
    '    return c.json({ error: { code: status === 404 ? \'NOT_FOUND\' : status === 422 ? \'INVALID_TRANSITION\' : \'INTERNAL_ERROR\', message }, correlationId }, status);',
    '  }',
    '});',
    '',
    "app.post('/api/v1/decisions/:id/reject', requireRole('approver', 'admin'), async (c) => {",
    '  const correlationId = c.get(\'correlationId\') as string;',
    '  const actor = ((c.get(\'iamClaims\') as Record<string, unknown>) ?? {})[\'sub\'] as string ?? \'unknown\';',
    '  const id = c.req.param(\'id\');',
    '  try {',
    '    const body = await c.req.json();',
    '    const reason = (body as Record<string, string>).reason;',
    '    if (!reason || reason.length < 10) return c.json(validationError(correlationId, [{ message: \'Rejection reason required (min 10 chars)\' }]), 400);',
    '    const result = await deps.decisions.reject(id, actor, reason);',
    '    await deps.audit.log(\'decisions\', id, \'rejected\', actor, { rejectedBy: actor, reason });',
    '    return c.json({ correlationId, status: \'rejected\', data: result }, 200);',
    '  } catch (err) {',
    '    console.error(JSON.stringify({ level: \'error\', correlationId, error: err instanceof Error ? err.message : String(err), path: c.req.path }));',
    '    const message = err instanceof Error ? err.message : \'Unknown error\';',
    '    return c.json(serverError(correlationId, message), message.includes(\'not found\') ? 404 : 500);',
    '  }',
    '});',
    '',
    "app.post('/api/v1/decisions/:id/execute', requireRole('erp_writer', 'admin'), async (c) => {",
    '  const correlationId = c.get(\'correlationId\') as string;',
    '  const actor = ((c.get(\'iamClaims\') as Record<string, unknown>) ?? {})[\'sub\'] as string ?? \'unknown\';',
    '  const id = c.req.param(\'id\');',
    '  try {',
    '    // ADR-054: Validate simulation lineage before ERP writeback',
    '    const lineageResult = await validateLineage(id, deps as unknown as { query: DbClient[\'query\'] });',
    '    if (!lineageResult.valid) {',
    '      await deps.audit.log(\'decisions\', id, \'execute:lineage_failed\', actor, { reason: lineageResult.reason });',
    '      return c.json({ error: { code: \'LINEAGE_INVALID\', message: lineageResult.reason }, correlationId }, 422);',
    '    }',
    '    const result = await deps.decisions.execute(id, actor);',
    '    await deps.audit.log(\'decisions\', id, \'executed\', actor, { executedBy: actor });',
    '    return c.json({ correlationId, status: \'executed\', data: result }, 200);',
    '  } catch (err) {',
    '    console.error(JSON.stringify({ level: \'error\', correlationId, error: err instanceof Error ? err.message : String(err), path: c.req.path }));',
    '    await deps.audit.log(\'decisions\', id, \'execute:failed\', actor, { error: err instanceof Error ? err.message : String(err) });',
    '    const message = err instanceof Error ? err.message : \'Unknown error\';',
    '    return c.json(serverError(correlationId, message), message.includes(\'not found\') ? 404 : 500);',
    '  }',
    '});',
    '',
    "app.get('/api/v1/decisions/:id', requireRole('viewer', 'writer', 'admin'), async (c) => {",
    '  const correlationId = c.get(\'correlationId\') as string;',
    '  const id = c.req.param(\'id\');',
    '  try {',
    '    const decision = await deps.decisions.getById(id);',
    '    if (!decision) return c.json({ error: { code: \'NOT_FOUND\', message: `Decision ${id} not found` }, correlationId }, 404);',
    '    return c.json({ correlationId, status: \'ok\', data: decision }, 200);',
    '  } catch (err) {',
    '    const message = process.env.NODE_ENV === \'production\' ? \'Internal server error\' : (err instanceof Error ? err.message : \'Unknown error\');',
    '    return c.json(serverError(correlationId, message), 500);',
    '  }',
    '});',
    '',
    "app.get('/api/v1/decisions', requireRole('viewer', 'writer', 'admin'), async (c) => {",
    '  const correlationId = c.get(\'correlationId\') as string;',
    "  const status = c.req.query('status') as import('./dependencies.js').DecisionStatus | undefined;",
    '  try {',
    '    const decisions = status ? await deps.decisions.listByStatus(status) : await deps.decisions.listByStatus(\'submitted\');',
    '    return c.json({ correlationId, status: \'ok\', data: decisions }, 200);',
    '  } catch (err) {',
    '    const message = process.env.NODE_ENV === \'production\' ? \'Internal server error\' : (err instanceof Error ? err.message : \'Unknown error\');',
    '    return c.json(serverError(correlationId, message), 500);',
    '  }',
    '});',
    '',
    "app.get('/api/v1/decisions/:id/lineage', requireRole('viewer', 'writer', 'admin'), async (c) => {",
    '  const correlationId = c.get(\'correlationId\') as string;',
    '  const id = c.req.param(\'id\');',
    '  try {',
    '    const decision = await deps.decisions.getById(id);',
    '    if (!decision) return c.json({ error: { code: \'NOT_FOUND\', message: `Decision ${id} not found` }, correlationId }, 404);',
    '    const lineage = await validateLineage(id, deps as unknown as { query: DbClient[\'query\'] });',
    '    return c.json({ correlationId, status: \'ok\', data: { decision, lineage } }, 200);',
    '  } catch (err) {',
    '    const message = process.env.NODE_ENV === \'production\' ? \'Internal server error\' : (err instanceof Error ? err.message : \'Unknown error\');',
    '    return c.json(serverError(correlationId, message), 500);',
    '  }',
    '});',
    '',
  );
  routeCount += 7; // submit, approve, reject, execute, getById, list, lineage

  // ADR-052: Simulation read-only endpoints (when simulation context available)
  if (simulationContext && (simulationContext.scenarios.length > 0 || simulationContext.simulationId)) {
    lines.push(
      '// ============================================================================',
      '// Simulation Endpoints (ADR-052) — read-only access to RuVector results',
      '// ============================================================================',
      '',
      "app.get('/api/v1/simulation/scenarios', requireRole('viewer', 'writer', 'admin'), async (c) => {",
      '  const correlationId = c.get(\'correlationId\') as string;',
      '  try {',
      '    const scenarios = await deps.simulation.getScenarios();',
      '    return c.json({ correlationId, status: \'ok\', data: scenarios, simulationId: deps.simulation.getSimulationId() }, 200);',
      '  } catch (err) {',
      '    const message = process.env.NODE_ENV === \'production\' ? \'Internal server error\' : (err instanceof Error ? err.message : \'Unknown error\');',
      '    return c.json(serverError(correlationId, message), 500);',
      '  }',
      '});',
      '',
      "app.get('/api/v1/simulation/scenarios/:id', requireRole('viewer', 'writer', 'admin'), async (c) => {",
      '  const correlationId = c.get(\'correlationId\') as string;',
      '  const id = c.req.param(\'id\');',
      '  try {',
      '    const scenario = await deps.simulation.getScenarioById(id);',
      '    if (!scenario) return c.json({ error: { code: \'NOT_FOUND\', message: `Scenario ${id} not found` }, correlationId }, 404);',
      '    return c.json({ correlationId, status: \'ok\', data: scenario }, 200);',
      '  } catch (err) {',
      '    const message = process.env.NODE_ENV === \'production\' ? \'Internal server error\' : (err instanceof Error ? err.message : \'Unknown error\');',
      '    return c.json(serverError(correlationId, message), 500);',
      '  }',
      '});',
      '',
      "app.get('/api/v1/simulation/compare', requireRole('viewer', 'writer', 'admin'), async (c) => {",
      '  const correlationId = c.get(\'correlationId\') as string;',
      "  const ids = (c.req.query('ids') ?? '').split(',').filter(Boolean);",
      '  try {',
      '    const comparison = await deps.simulation.compareScenarios(ids);',
      '    return c.json({ correlationId, status: \'ok\', data: comparison }, 200);',
      '  } catch (err) {',
      '    const message = process.env.NODE_ENV === \'production\' ? \'Internal server error\' : (err instanceof Error ? err.message : \'Unknown error\');',
      '    return c.json(serverError(correlationId, message), 500);',
      '  }',
      '});',
      '',
      "app.get('/api/v1/simulation/cost-model', requireRole('viewer', 'writer', 'admin'), async (c) => {",
      '  const correlationId = c.get(\'correlationId\') as string;',
      '  try {',
      '    const costModel = await deps.simulation.getCostModel();',
      '    return c.json({ correlationId, status: \'ok\', data: costModel, simulationId: deps.simulation.getSimulationId() }, 200);',
      '  } catch (err) {',
      '    const message = process.env.NODE_ENV === \'production\' ? \'Internal server error\' : (err instanceof Error ? err.message : \'Unknown error\');',
      '    return c.json(serverError(correlationId, message), 500);',
      '  }',
      '});',
      '',
    );
    routeCount += 4;

    // ADR-053: Tradeoff analysis and budget compliance endpoints
    lines.push(
      '// ============================================================================',
      '// Cost & Tradeoff Endpoints (ADR-053) — CostOps financial model',
      '// ============================================================================',
      '',
      "app.get('/api/v1/cost/tradeoff-matrix', requireRole('viewer', 'writer', 'admin'), async (c) => {",
      '  const correlationId = c.get(\'correlationId\') as string;',
      '  try {',
      "    const matrixPath = require('node:path').join(__dirname, '..', 'data', 'tradeoff-matrix.json');",
      "    const matrix = JSON.parse(require('node:fs').readFileSync(matrixPath, 'utf-8'));",
      '    return c.json({ correlationId, status: \'ok\', data: matrix }, 200);',
      '  } catch {',
      '    return c.json({ correlationId, status: \'ok\', data: { dimensions: [], scenarios: [], costModel: null } }, 200);',
      '  }',
      '});',
      '',
      "app.get('/api/v1/cost/budget-compliance', requireRole('viewer', 'writer', 'admin'), async (c) => {",
      '  const correlationId = c.get(\'correlationId\') as string;',
      '  try {',
      '    const costModel = await deps.simulation.getCostModel();',
      '    if (!costModel) return c.json({ correlationId, status: \'ok\', data: { compliant: true, message: \'No cost model available\' } }, 200);',
      '    const scenarios = await deps.simulation.getScenarios();',
      '    const overBudget = scenarios.filter(s => costModel.budgetThreshold > 0 && s.costDelta > costModel.budgetThreshold);',
      '    return c.json({',
      '      correlationId,',
      '      status: \'ok\',',
      '      data: {',
      '        compliant: overBudget.length === 0,',
      '        budgetThreshold: costModel.budgetThreshold,',
      '        roi: costModel.roi,',
      '        confidence: costModel.confidence,',
      '        scenariosOverBudget: overBudget.map(s => ({ id: s.id, name: s.name, costDelta: s.costDelta })),',
      '        totalScenarios: scenarios.length,',
      '      },',
      '    }, 200);',
      '  } catch (err) {',
      '    const message = process.env.NODE_ENV === \'production\' ? \'Internal server error\' : (err instanceof Error ? err.message : \'Unknown error\');',
      '    return c.json(serverError(correlationId, message), 500);',
      '  }',
      '});',
      '',
    );
    routeCount += 2;
  }

  // ERP sync status endpoint (reusable across all ERP types)
  lines.push(
    '// ============================================================================',
    '// GET /api/v1/erp/sync-status — ERP sync queue and circuit breaker',
    '// ============================================================================',
    '',
    'app.get(\'/api/v1/erp/sync-status\', async (c) => {',
    '  const correlationId = c.get(\'correlationId\') as string;',
    '  const startTime = Date.now();',
    '  try {',
    '    const status = erpClientInstance.getSyncStatus();',
    '    return c.json({',
    '      correlationId,',
    '      status: \'ok\',',
    '      data: status,',
    '      metadata: { response_time_ms: Date.now() - startTime },',
    '    }, 200);',
    '  } catch (err) {',
    '    const message = process.env.NODE_ENV === \'production\' ? \'Internal server error\' : (err instanceof Error ? err.message : \'Unknown error\');',
    '    return c.json(serverError(correlationId, message), 500);',
    '  }',
    '});',
    '',
    '',
    '// ============================================================================',
    '// GET /metrics — Prometheus-compatible metrics (ADR-051)',
    '// ============================================================================',
    '',
    'app.get(\'/metrics\', (c) => {',
    '  const m = (deps as Record<string, unknown>)[\'_telemetry\'] as { metrics?: { requestCount: number; errorCount: number; latencySumMs: number; spanCount: number; byOperation: Record<string, { count: number; errors: number; totalMs: number }> } } | undefined;',
    '  const metrics = m?.metrics ?? { requestCount: 0, errorCount: 0, latencySumMs: 0, spanCount: 0, byOperation: {} };',
    '  const lines: string[] = [];',
    '  lines.push(\'# HELP http_requests_total Total HTTP requests processed\');',
    '  lines.push(\'# TYPE http_requests_total counter\');',
    '  lines.push(`http_requests_total ${metrics.requestCount}`);',
    '  lines.push(\'# HELP http_errors_total Total HTTP errors\');',
    '  lines.push(\'# TYPE http_errors_total counter\');',
    '  lines.push(`http_errors_total ${metrics.errorCount}`);',
    '  lines.push(\'# HELP http_spans_total Total telemetry spans\');',
    '  lines.push(\'# TYPE http_spans_total counter\');',
    '  lines.push(`http_spans_total ${metrics.spanCount}`);',
    '  lines.push(\'# HELP http_latency_sum_ms Sum of all span latencies in ms\');',
    '  lines.push(\'# TYPE http_latency_sum_ms counter\');',
    '  lines.push(`http_latency_sum_ms ${metrics.latencySumMs}`);',
    '  for (const [op, data] of Object.entries(metrics.byOperation)) {',
    '    lines.push(`http_operation_count{operation="${op}"} ${data.count}`);',
    '    lines.push(`http_operation_errors{operation="${op}"} ${data.errors}`);',
    '    lines.push(`http_operation_latency_ms{operation="${op}"} ${data.totalMs}`);',
    '  }',
    '  return c.text(lines.join(\'\\n\'));',
    '});',
    '',
    'export { app, erpClientInstance };',
    '',
  );
  routeCount += 2; // sync-status + metrics

  return { content: lines.join('\n'), routeCount };
}

// ============================================================================
// TypeScript Middleware, Health (unchanged)
// ============================================================================

function tsMiddleware(): string {
  return [
    GENERATED_HEADER_TS,
    `import type { MiddlewareHandler } from 'hono';`,
    `import { createMiddleware } from 'hono/factory';`,
    `import * as crypto from 'node:crypto';`,
    `import * as jwt from 'jsonwebtoken';`,
    `import jwksClient from 'jwks-rsa';`,
    '',
    '// ---------------------------------------------------------------------------',
    '// Correlation ID middleware',
    '// ---------------------------------------------------------------------------',
    '',
    'export const correlationMiddleware: MiddlewareHandler = createMiddleware(async (c, next) => {',
    '  const correlationId = c.req.header(\'X-Correlation-ID\') ?? crypto.randomUUID();',
    '  c.set(\'correlationId\', correlationId);',
    '  c.header(\'X-Correlation-ID\', correlationId);',
    '  await next();',
    '});',
    '',
    '// ---------------------------------------------------------------------------',
    '// IAM token validation middleware (JWKS-backed JWT verification)',
    '// ---------------------------------------------------------------------------',
    '',
    'const JWKS_URI = process.env.IAM_JWKS_URI ?? \'https://www.googleapis.com/oauth2/v3/certs\';',
    'const IAM_AUDIENCE = process.env.IAM_AUDIENCE ?? \'\';',
    'const IAM_ISSUERS = (process.env.IAM_ISSUERS ?? \'https://accounts.google.com\').split(\',\').map(s => s.trim());',
    '',
    'const jwksRsa = jwksClient({',
    '  jwksUri: JWKS_URI,',
    '  cache: true,',
    '  cacheMaxAge: 600_000,',
    '  rateLimit: true,',
    '  jwksRequestsPerMinute: 10,',
    '});',
    '',
    'function getSigningKey(kid: string): Promise<string> {',
    '  return new Promise((resolve, reject) => {',
    '    jwksRsa.getSigningKey(kid, (err, key) => {',
    '      if (err || !key) return reject(err ?? new Error(\'No signing key found\'));',
    '      resolve(key.getPublicKey());',
    '    });',
    '  });',
    '}',
    '',
    'export const iamMiddleware: MiddlewareHandler = createMiddleware(async (c, next) => {',
    '  const path = new URL(c.req.url).pathname;',
    '  if (path === \'/health/healthz\' || path === \'/health/readyz\') {',
    '    await next();',
    '    return;',
    '  }',
    '',
    '  // ADR-051: Auth errors include correlationId for traceability',
    '  const correlationId = c.get(\'correlationId\') as string ?? \'unknown\';',
    '  const authHeader = c.req.header(\'Authorization\');',
    '  if (!authHeader?.startsWith(\'Bearer \')) {',
    '    return c.json({ error: { code: \'UNAUTHORIZED\', message: \'Missing Bearer token\' }, correlationId }, 401);',
    '  }',
    '',
    '  const token = authHeader.slice(7);',
    '  if (!token) {',
    '    return c.json({ error: { code: \'UNAUTHORIZED\', message: \'Empty token\' }, correlationId }, 401);',
    '  }',
    '',
    '  try {',
    '    const decoded = jwt.decode(token, { complete: true });',
    '    if (!decoded || typeof decoded === \'string\' || !decoded.header.kid) {',
    '      return c.json({ error: { code: \'UNAUTHORIZED\', message: \'Malformed token: missing kid\' } }, 401);',
    '    }',
    '',
    '    const signingKey = await getSigningKey(decoded.header.kid);',
    '',
    '    const verifyOptions: jwt.VerifyOptions = {',
    '      algorithms: [\'RS256\', \'RS384\', \'RS512\', \'ES256\', \'ES384\'],',
    '    };',
    '    if (IAM_ISSUERS.length > 0 && IAM_ISSUERS[0] !== \'\') {',
    '      verifyOptions.issuer = IAM_ISSUERS;',
    '    }',
    '    if (IAM_AUDIENCE) {',
    '      verifyOptions.audience = IAM_AUDIENCE;',
    '    }',
    '',
    '    const payload = jwt.verify(token, signingKey, verifyOptions);',
    '    c.set(\'iamClaims\', payload);',
    '  } catch (err) {',
    '    const message = err instanceof Error ? err.message : \'Token verification failed\';',
    '    console.warn(JSON.stringify({ level: \'warn\', type: \'AUTH_FAILURE\', correlationId, error: message, path: c.req.path }));',
    '    return c.json({ error: { code: \'UNAUTHORIZED\', message }, correlationId }, 401);',
    '  }',
    '',
    '  await next();',
    '});',
    '',
    '// ---------------------------------------------------------------------------',
    '// Structured JSON request/response logging middleware',
    '// ---------------------------------------------------------------------------',
    '',
    'export const loggingMiddleware: MiddlewareHandler = createMiddleware(async (c, next) => {',
    '  const startTime = Date.now();',
    '  const correlationId = c.get(\'correlationId\') as string | undefined;',
    '',
    '  process.stdout.write(',
    '    JSON.stringify({',
    '      severity: \'INFO\',',
    '      message: \'request received\',',
    '      httpRequest: {',
    '        method: c.req.method,',
    '        url: c.req.url,',
    '        userAgent: c.req.header(\'user-agent\'),',
    '      },',
    '      correlationId,',
    '      timestamp: new Date().toISOString(),',
    '    }) + \'\\n\',',
    '  );',
    '',
    '  await next();',
    '',
    '  const durationMs = Date.now() - startTime;',
    '  process.stdout.write(',
    '    JSON.stringify({',
    '      severity: \'INFO\',',
    '      message: \'request completed\',',
    '      httpRequest: {',
    '        method: c.req.method,',
    '        url: c.req.url,',
    '        status: c.res.status,',
    '        latency: `${durationMs}ms`,',
    '      },',
    '      correlationId,',
    '      timestamp: new Date().toISOString(),',
    '    }) + \'\\n\',',
    '  );',
    '});',
    '',
  ].join('\n');
}

function tsHealth(): string {
  return [
    GENERATED_HEADER_TS,
    `import { Hono } from 'hono';`,
    '',
    '// ADR-050: Real health checks that verify downstream dependencies',
    'export function createHealthRouter(deps: {',
    '  db?: { query(sql: string, params: unknown[]): Promise<unknown[]> };',
    '  erp?: { getSyncStatus(): { circuit_breaker_state: string } };',
    '}): Hono {',
    '  const healthRouter = new Hono();',
    '',
    '  // Liveness — is the process running?',
    '  healthRouter.get(\'/healthz\', (c) => {',
    '    return c.json({ status: \'ok\' }, 200);',
    '  });',
    '',
    '  // Readiness — can the service handle requests?',
    '  healthRouter.get(\'/readyz\', async (c) => {',
    '    const checks: Record<string, \'ok\' | \'fail\'> = {};',
    '',
    '    // Database connectivity check',
    '    if (deps.db) {',
    '      try {',
    '        await deps.db.query(\'SELECT 1\', []);',
    '        checks.database = \'ok\';',
    '      } catch {',
    '        checks.database = \'fail\';',
    '      }',
    '    }',
    '',
    '    // ERP circuit breaker check',
    '    if (deps.erp) {',
    '      try {',
    '        const status = deps.erp.getSyncStatus();',
    '        checks.erp = status.circuit_breaker_state === \'open\' ? \'fail\' : \'ok\';',
    '      } catch {',
    '        checks.erp = \'fail\';',
    '      }',
    '    }',
    '',
    '    const allOk = Object.values(checks).every(v => v === \'ok\');',
    '    return c.json({',
    '      status: allOk ? \'ready\' : \'degraded\',',
    '      checks,',
    '    }, allOk ? 200 : 503);',
    '  });',
    '',
    '  return healthRouter;',
    '}',
    '',
    '// Backwards-compatible default export for simple usage',
    'export const healthRouter = createHealthRouter({});',
    '',
  ].join('\n');
}

