function rustRoutes(
  contexts: readonly { name: string; commands: readonly { name: string }[]; queries: readonly { name: string }[]; entities?: readonly { name: string; description: string }[]; valueObjects?: readonly { name: string; description: string }[] }[],
): { content: string; routeCount: number } {
  const lines: string[] = [
    GENERATED_HEADER_RS,
    'use axum::{',
    '    extract::Query,',
    '    http::StatusCode,',
    '    response::Json,',
    '    routing::{get, post},',
    '    Router,',
    '};',
    'use serde_json::{json, Value};',
    'use std::collections::HashMap;',
    'use tokio;',
    '',
    'pub fn create_router() -> Router {',
    '    Router::new()',
    '        .route("/health/healthz", get(crate::health::healthz))',
    '        .route("/health/readyz", get(crate::health::readyz))',
  ];

  let routeCount = 0;

  for (const ctx of contexts) {
    const ctxSlug = slugify(ctx.name.replace(/Context$/i, ''));

    for (const cmd of ctx.commands) {
      const cmdSlug = slugify(cmd.name);
      const fnName = snakeCase(cmd.name);
      lines.push(`        .route("/api/${ctxSlug}/${cmdSlug}", post(handle_${fnName}))`);
      routeCount++;
    }

    for (const query of ctx.queries) {
      const querySlug = slugify(query.name);
      const fnName = snakeCase(query.name);
      lines.push(`        .route("/api/${ctxSlug}/${querySlug}", get(handle_${fnName}))`);
      routeCount++;
    }
  }

  lines.push('}');
  lines.push('');

  for (const ctx of contexts) {
    const ctxSlug = slugify(ctx.name.replace(/Context$/i, ''));
    lines.push(`// Bounded context: ${ctx.name}`);

    for (const cmd of ctx.commands) {
      const fnName = snakeCase(cmd.name);
      const cmdSlug = slugify(cmd.name);
      lines.push(`async fn handle_${fnName}(`);
      lines.push(`    Json(body): Json<Value>,`);
      lines.push(`) -> Result<Json<Value>, StatusCode> {`);
      lines.push(`    let start = std::time::Instant::now();`);
      lines.push(buildRustMockCommandJson(ctxSlug, cmdSlug));
      lines.push(`}`);
      lines.push('');
    }

    for (const query of ctx.queries) {
      const fnName = snakeCase(query.name);
      const querySlug = slugify(query.name);
      lines.push(`async fn handle_${fnName}(`);
      lines.push(`    Query(params): Query<HashMap<String, String>>,`);
      lines.push(`) -> Result<Json<Value>, StatusCode> {`);
      lines.push(buildRustMockQueryJson(ctxSlug, querySlug));
      lines.push(`}`);
      lines.push('');
    }
  }

  return { content: lines.join('\n'), routeCount };
}

function rustMiddleware(): string {
  return [
    GENERATED_HEADER_RS,
    'use axum::{',
    '    body::Body,',
    '    http::{Request, Response},',
    '    middleware::Next,',
    '    response::IntoResponse,',
    '};',
    'use uuid::Uuid;',
    '',
    'pub async fn correlation_middleware(',
    '    mut req: Request<Body>,',
    '    next: Next<Body>,',
    ') -> impl IntoResponse {',
    '    let correlation_id = req',
    '        .headers()',
    '        .get("x-correlation-id")',
    '        .and_then(|v| v.to_str().ok())',
    '        .map(|s| s.to_string())',
    '        .unwrap_or_else(|| Uuid::new_v4().to_string());',
    '',
    '    req.extensions_mut().insert(correlation_id.clone());',
    '',
    '    let mut response = next.run(req).await;',
    '    response.headers_mut().insert(',
    '        "x-correlation-id",',
    '        correlation_id.parse().unwrap(),',
    '    );',
    '    response',
    '}',
    '',
    'fn jwks_uri() -> String {',
    '    std::env::var("IAM_JWKS_URI")',
    '        .unwrap_or_else(|_| "https://www.googleapis.com/oauth2/v3/certs".into())',
    '}',
    '',
    'fn iam_audience() -> Option<String> {',
    '    std::env::var("IAM_AUDIENCE").ok().filter(|s| !s.is_empty())',
    '}',
    '',
    'fn iam_issuers() -> Vec<String> {',
    '    std::env::var("IAM_ISSUERS")',
    '        .unwrap_or_else(|_| "https://accounts.google.com".into())',
    '        .split(\',\')',
    '        .map(|s| s.trim().to_string())',
    '        .filter(|s| !s.is_empty())',
    '        .collect()',
    '}',
    '',
    'pub async fn iam_middleware(',
    '    req: Request<Body>,',
    '    next: Next<Body>,',
    ') -> impl IntoResponse {',
    '    let path = req.uri().path().to_string();',
    '    if path == "/health/healthz" || path == "/health/readyz" {',
    '        return next.run(req).await.into_response();',
    '    }',
    '',
    '    let auth_header = req',
    '        .headers()',
    '        .get("authorization")',
    '        .and_then(|v| v.to_str().ok())',
    '        .map(|s| s.to_string());',
    '',
    '    match auth_header {',
    '        Some(header) if header.starts_with("Bearer ") => {',
    '            let token = &header[7..];',
    '            let header = match jsonwebtoken::decode_header(token) {',
    '                Ok(h) => h,',
    '                Err(_) => return unauthorized("Malformed token header"),',
    '            };',
    '            let kid = match header.kid {',
    '                Some(k) => k,',
    '                None => return unauthorized("Token missing kid claim"),',
    '            };',
    '',
    '            let jwks_url = jwks_uri();',
    '            let jwks = match reqwest::get(&jwks_url).await {',
    '                Ok(resp) => match resp.json::<jsonwebtoken::jwk::JwkSet>().await {',
    '                    Ok(set) => set,',
    '                    Err(_) => return unauthorized("Failed to parse JWKS"),',
    '                },',
    '                Err(_) => return unauthorized("Failed to fetch JWKS"),',
    '            };',
    '',
    '            let jwk = match jwks.find(&kid) {',
    '                Some(k) => k,',
    '                None => return unauthorized("No matching key in JWKS"),',
    '            };',
    '',
    '            let decoding_key = match jsonwebtoken::DecodingKey::from_jwk(jwk) {',
    '                Ok(k) => k,',
    '                Err(_) => return unauthorized("Invalid JWK"),',
    '            };',
    '',
    '            let mut validation = jsonwebtoken::Validation::new(header.alg);',
    '            let issuers = iam_issuers();',
    '            if !issuers.is_empty() {',
    '                validation.set_issuer(&issuers);',
    '            }',
    '            if let Some(aud) = iam_audience() {',
    '                validation.set_audience(&[aud]);',
    '            } else {',
    '                validation.validate_aud = false;',
    '            }',
    '',
    '            match jsonwebtoken::decode::<serde_json::Value>(token, &decoding_key, &validation) {',
    '                Ok(_) => next.run(req).await.into_response(),',
    '                Err(e) => unauthorized(&format!("Token verification failed: {e}")),',
    '            }',
    '        }',
    '        _ => unauthorized("Missing Bearer token"),',
    '    }',
    '}',
    '',
    'fn unauthorized(msg: &str) -> axum::http::Response<axum::body::Body> {',
    '    axum::http::Response::builder()',
    '        .status(401)',
    '        .header("content-type", "application/json")',
    '        .body(axum::body::Body::from(',
    '            serde_json::json!({"error":{"code":"UNAUTHORIZED","message":msg}}).to_string()',
    '        ))',
    '        .unwrap()',
    '}',
    '',
    'pub async fn logging_middleware(',
    '    req: Request<Body>,',
    '    next: Next<Body>,',
    ') -> impl IntoResponse {',
    '    let method = req.method().clone();',
    '    let uri = req.uri().clone();',
    '    let start = std::time::Instant::now();',
    '',
    '    println!("{}", serde_json::json!({',
    '        "severity": "INFO",',
    '        "message": "request received",',
    '        "httpRequest": { "method": method.as_str(), "url": uri.to_string() },',
    '        "timestamp": chrono::Utc::now().to_rfc3339()',
    '    }));',
    '',
    '    let response = next.run(req).await;',
    '    let duration_ms = start.elapsed().as_millis();',
    '',
    '    println!("{}", serde_json::json!({',
    '        "severity": "INFO",',
    '        "message": "request completed",',
    '        "httpRequest": {',
    '            "method": method.as_str(),',
    '            "url": uri.to_string(),',
    '            "status": response.status().as_u16(),',
    '            "latency": format!("{}ms", duration_ms)',
    '        },',
    '        "timestamp": chrono::Utc::now().to_rfc3339()',
    '    }));',
    '',
    '    response',
    '}',
    '',
  ].join('\n');
}

function rustHealth(): string {
  return [
    GENERATED_HEADER_RS,
    'use axum::{http::StatusCode, response::Json};',
    'use serde_json::{json, Value};',
    '',
    'pub async fn healthz() -> (StatusCode, Json<Value>) {',
    '    (StatusCode::OK, Json(json!({ "status": "ok" })))',
    '}',
    '',
    'pub async fn readyz() -> (StatusCode, Json<Value>) {',
    '    (StatusCode::OK, Json(json!({ "status": "ready" })))',
    '}',
    '',
  ].join('\n');
}

// ============================================================================
// File Writing
// ============================================================================

function writeServerFile(absPath: string, content: string): void {
  const dir = absPath.substring(0, absPath.lastIndexOf('/'));
  mkdirSync(dir, { recursive: true, mode: DIR_MODE });
  try {
    writeFileSync(absPath, content, { encoding: 'utf-8', mode: FILE_MODE });
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    throw new Error(`ECLI-P4-051: Failed to write server file ${absPath}: ${message}`);
  }
}

// ============================================================================
// Public: Pipeline Entry Point
// ============================================================================

export function generateHttpServer(context: Phase4Context): Phase4StageOutput {
  const startTime = Date.now();
  const rootSpan = createSpan('http-server-generation', 'generate-http-server', {
    phase4Dir: context.phase4Dir,
    traceId: context.traceId,
  });

  try {
    // Verify ERP target resolution completed
    const erpStage = context.stageOutputs.get('erp-target-resolution');
    if (!erpStage || erpStage.status !== 'completed') {
      throw new Error(
        'ECLI-P4-050: ERP target resolution not available on context. ' +
        'Ensure the erp-target-resolution stage completed successfully before running http-server-generation.',
      );
    }
    const erpResolution = erpStage.data as ERPResolution;

    // Resolve implementation language and bounded contexts
    const language = context.phase3Artifacts.implementationLanguage;

    // Non-TS/Rust languages handled by Ruflo swarm
    if (!hasTemplateSupport(language)) {
      const span = endSpan(rootSpan, 'ok', { delegated: true, language });
      emitSpan(span);
      return {
        stage: 'http-server-generation',
        status: 'completed',
        data: { framework: 'hono', files: [], routeCount: 0 } satisfies HttpServerOutput,
        artifacts: [],
        timing: Date.now() - startTime,
        summary: `HTTP server for ${language} delegated to Ruflo swarm.`,
      };
    }

    const domainModel = context.phase3Artifacts.phase2Artifacts.domainModel;

    // Flatten commands/queries/entities/VOs from aggregates to context level for route generation.
    const contexts = (domainModel.contexts as unknown as readonly Record<string, unknown>[]).map((ctx) => {
      const aggregates = (ctx['aggregates'] as readonly Record<string, unknown>[] | undefined) ?? [];
      const commands: { name: string; description?: string; input?: readonly string[]; preconditions?: readonly string[]; postconditions?: readonly string[] }[] = [];
      const queries: { name: string; description?: string; parameters?: readonly string[]; returns?: string }[] = [];
      const entities: { name: string; description: string }[] = [];
      const valueObjects: { name: string; description: string }[] = [];
      const domainEvents: { name: string; description?: string; payload?: readonly string[]; triggeredBy?: string }[] = [];
      const invariants: string[] = [];

      for (const agg of aggregates) {
        const aggCommands = (agg['commands'] as readonly Record<string, unknown>[] | undefined) ?? [];
        const aggQueries = (agg['queries'] as readonly Record<string, unknown>[] | undefined) ?? [];
        const aggEntities = (agg['entities'] as readonly Record<string, unknown>[] | undefined) ?? [];
        const aggVOs = (agg['valueObjects'] as readonly Record<string, unknown>[] | undefined) ?? [];

        for (const cmd of aggCommands) {
          commands.push({
            name: cmd['name'] as string,
            description: (cmd['description'] as string | undefined) ?? '',
            input: (cmd['input'] as readonly string[] | undefined) ?? [],
            preconditions: (cmd['preconditions'] as readonly string[] | undefined) ?? [],
            postconditions: (cmd['postconditions'] as readonly string[] | undefined) ?? [],
          });
        }
        for (const q of aggQueries) {
          queries.push({
            name: q['name'] as string,
            description: (q['description'] as string | undefined) ?? '',
            parameters: (q['parameters'] as readonly string[] | undefined) ?? [],
            returns: (q['returns'] as string | undefined) ?? 'unknown',
          });
        }
        for (const ent of aggEntities) {
          entities.push({ name: ent['name'] as string, description: (ent['description'] as string | undefined) ?? '' });
        }
        for (const vo of aggVOs) {
          valueObjects.push({ name: vo['name'] as string, description: (vo['description'] as string | undefined) ?? '' });
        }

        // Extract domain events from aggregate
        const aggEvents = (agg['domainEvents'] as readonly Record<string, unknown>[] | undefined) ?? [];
        for (const evt of aggEvents) {
          domainEvents.push({
            name: evt['name'] as string,
            description: (evt['description'] as string | undefined) ?? '',
            payload: (evt['payload'] as readonly string[] | undefined) ?? [],
            triggeredBy: (evt['triggeredBy'] as string | undefined) ?? '',
          });
        }

        // Extract invariants from aggregate
        const aggInvariants = (agg['invariants'] as readonly string[] | undefined) ?? [];
        for (const inv of aggInvariants) {
          if (typeof inv === 'string') invariants.push(inv);
        }
      }

      const ctxCommands = (ctx['commands'] as readonly Record<string, unknown>[] | undefined) ?? [];
      const ctxQueries = (ctx['queries'] as readonly Record<string, unknown>[] | undefined) ?? [];
      for (const cmd of ctxCommands) {
        commands.push({
          name: (cmd as Record<string, unknown>)['name'] as string,
          description: ((cmd as Record<string, unknown>)['description'] as string | undefined) ?? '',
          input: ((cmd as Record<string, unknown>)['input'] as readonly string[] | undefined) ?? [],
          preconditions: ((cmd as Record<string, unknown>)['preconditions'] as readonly string[] | undefined) ?? [],
          postconditions: ((cmd as Record<string, unknown>)['postconditions'] as readonly string[] | undefined) ?? [],
        });
      }
      for (const q of ctxQueries) {
        queries.push({
          name: (q as Record<string, unknown>)['name'] as string,
          description: ((q as Record<string, unknown>)['description'] as string | undefined) ?? '',
          parameters: ((q as Record<string, unknown>)['parameters'] as readonly string[] | undefined) ?? [],
          returns: ((q as Record<string, unknown>)['returns'] as string | undefined) ?? 'unknown',
        });
      }

      // Also extract context-level domain events
      const ctxEvents = (ctx['domainEvents'] as readonly Record<string, unknown>[] | undefined) ?? [];
      for (const evt of ctxEvents) {
        domainEvents.push({
          name: (evt as Record<string, unknown>)['name'] as string,
          description: ((evt as Record<string, unknown>)['description'] as string | undefined) ?? '',
          payload: ((evt as Record<string, unknown>)['payload'] as readonly string[] | undefined) ?? [],
          triggeredBy: ((evt as Record<string, unknown>)['triggeredBy'] as string | undefined) ?? '',
        });
      }

      return { name: ctx['name'] as string, commands, queries, entities, valueObjects, domainEvents, invariants };
    });

    const isTs = language === 'typescript';
    const framework: 'hono' | 'axum' = isTs ? 'hono' : 'axum';

    // Output directory: phase4/project/src/server/
    const serverDir = join(context.phase4Dir, 'project', 'src', 'server');
    mkdirSync(serverDir, { recursive: true, mode: DIR_MODE });

    const serverFiles: ServerFile[] = [];
    const writtenPaths: string[] = [];

    const genSpan = createSpan(
      'http-server-generation',
      'generate-files',
      { language, framework, contextCount: contexts.length },
      rootSpan.spanId,
    );

    if (isTs) {
      // main.ts
      const mainContent = tsMain();
      const mainPath = join(serverDir, 'main.ts');
      writeServerFile(mainPath, mainContent);
      serverFiles.push({ relativePath: 'project/src/server/main.ts', content: mainContent, kind: 'server' });
      writtenPaths.push(mainPath);

      // schemas.ts — Zod validation schemas for all domain entities
      const schemasContent = tsSchemas(contexts);
      const schemasPath = join(serverDir, 'schemas.ts');
      writeServerFile(schemasPath, schemasContent);
      serverFiles.push({ relativePath: 'project/src/server/schemas.ts', content: schemasContent, kind: 'server' });
      writtenPaths.push(schemasPath);

      // dependencies.ts — DI factory with port interfaces, adapters, and container
      const simCtx = context.simulationContext ?? null;
      const depsContent = tsDependencies(contexts, simCtx);
      const depsPath = join(serverDir, 'dependencies.ts');
      writeServerFile(depsPath, depsContent);
      serverFiles.push({ relativePath: 'project/src/server/dependencies.ts', content: depsContent, kind: 'server' });
      writtenPaths.push(depsPath);

      // simulation-context.json — ADR-052: embed simulation results in generated project
      if (simCtx && (simCtx.scenarios.length > 0 || simCtx.simulationId)) {
        const dataDir = join(context.phase4Dir, 'project', 'src', 'data');
        mkdirSync(dataDir, { recursive: true, mode: DIR_MODE });

        const simContextPath = join(dataDir, 'simulation-context.json');
        writeFileSync(simContextPath, JSON.stringify(simCtx, null, 2) + '\n', { encoding: 'utf-8', mode: FILE_MODE });
        writtenPaths.push(simContextPath);
        serverFiles.push({ relativePath: 'project/src/data/simulation-context.json', content: JSON.stringify(simCtx, null, 2), kind: 'server' });

        // ADR-053: Generate tradeoff-matrix.json for multi-dimensional comparison
        if (simCtx.scenarios.length > 0) {
          const tradeoffMatrix = {
            dimensions: ['cost', 'emissions', 'resilience', 'complexity'],
            scenarios: simCtx.scenarios.map(s => ({
              id: s.id,
              name: s.name,
              scores: {
                cost: Math.max(0, Math.min(1, 1 - Math.abs(s.costDelta) / 10_000_000)), // normalize cost
                emissions: s.reliability, // use reliability as proxy for emissions improvement
                resilience: s.riskLevel === 'low' ? 0.9 : s.riskLevel === 'medium' ? 0.6 : 0.3,
                complexity: s.mitigationStrategy ? 0.5 : 0.8, // strategies with mitigations are more complex
              },
              costDelta: s.costDelta,
              riskLevel: s.riskLevel,
            })),
            costModel: simCtx.costModel,
            generatedAt: new Date().toISOString(),
          };
          const tradeoffPath = join(dataDir, 'tradeoff-matrix.json');
          writeFileSync(tradeoffPath, JSON.stringify(tradeoffMatrix, null, 2) + '\n', { encoding: 'utf-8', mode: FILE_MODE });
          writtenPaths.push(tradeoffPath);
          serverFiles.push({ relativePath: 'project/src/data/tradeoff-matrix.json', content: JSON.stringify(tradeoffMatrix, null, 2), kind: 'server' });
        }
      }

      // routes.ts — Domain logic route handlers wired to adapters
      const { content: routesContent, routeCount } = tsRoutes(erpResolution.erpSystem, contexts, simCtx);
      const routesPath = join(serverDir, 'routes.ts');
      writeServerFile(routesPath, routesContent);
      serverFiles.push({ relativePath: 'project/src/server/routes.ts', content: routesContent, kind: 'server' });
      writtenPaths.push(routesPath);

      // middleware.ts
      const middlewareContent = tsMiddleware();
      const middlewarePath = join(serverDir, 'middleware.ts');
      writeServerFile(middlewarePath, middlewareContent);
      serverFiles.push({ relativePath: 'project/src/server/middleware.ts', content: middlewareContent, kind: 'server' });
      writtenPaths.push(middlewarePath);

      // health.ts
      const healthContent = tsHealth();
      const healthPath = join(serverDir, 'health.ts');
      writeServerFile(healthPath, healthContent);
      serverFiles.push({ relativePath: 'project/src/server/health.ts', content: healthContent, kind: 'server' });
      writtenPaths.push(healthPath);

      // package.json — ensure project root has build config
      const projectDir = join(context.phase4Dir, 'project');
      const pkgJsonPath = join(projectDir, 'package.json');
      // Derive package name from scenario query — not "generated-prototype"
      const pkgName = (context.scenarioQuery ?? '')
        .toLowerCase().replace(/[^a-z0-9\s-]/g, ' ').split(/\s+/)
        .filter(w => w.length > 2 && !['the','and','for','with','from','that','this','our','are','was','has','have','been','will','would','could','should','can','build','create','make','implement','develop','using','need','want','lead','global','company','approximately','employees','one','biggest','challenges'].includes(w))
        .slice(0, 4).join('-') || 'enterprise-service';
      const pkgJson = JSON.stringify({
        name: pkgName,
        version: '0.1.0',
        type: 'module',
        main: './dist/server/main.js',
        scripts: {
          build: 'tsc',
          start: 'node dist/server/main.js',
          dev: 'tsx watch src/server/main.ts',
          test: 'vitest run',
          'test:watch': 'vitest',
          lint: 'tsc --noEmit',
        },
        dependencies: {
          hono: '^4.0.0',
          zod: '^3.22.0',
          jsonwebtoken: '^9.0.0',
          'jwks-rsa': '^3.1.0',
        },
        devDependencies: {
          '@types/node': '^20.0.0',
          '@types/jsonwebtoken': '^9.0.0',
          '@types/better-sqlite3': '^7.6.0',
          'better-sqlite3': '^11.0.0',
          typescript: '^5.4.0',
          tsx: '^4.0.0',
          vitest: '^1.6.0',
        },
      }, null, 2) + '\n';
      writeServerFile(pkgJsonPath, pkgJson);
      serverFiles.push({ relativePath: 'project/package.json', content: pkgJson, kind: 'server' });
      writtenPaths.push(pkgJsonPath);

      // tsconfig.json
      const tsconfigPath = join(projectDir, 'tsconfig.json');
      const tsconfig = JSON.stringify({
        compilerOptions: {
          target: 'ES2022',
          module: 'NodeNext',
          moduleResolution: 'NodeNext',
          strict: true,
          outDir: 'dist',
          rootDir: 'src',
          declaration: true,
          esModuleInterop: true,
          skipLibCheck: true,
          forceConsistentCasingInFileNames: true,
          resolveJsonModule: true,
        },
        include: ['src'],
        exclude: ['node_modules', 'dist'],
      }, null, 2) + '\n';
      writeServerFile(tsconfigPath, tsconfig);
      serverFiles.push({ relativePath: 'project/tsconfig.json', content: tsconfig, kind: 'server' });
      writtenPaths.push(tsconfigPath);

      // vitest.config.ts
      const vitestPath = join(projectDir, 'vitest.config.ts');
      const vitestContent = [
        GENERATED_HEADER_TS,
        `import { defineConfig } from 'vitest/config';`,
        '',
        'export default defineConfig({',
        '  test: {',
        '    globals: true,',
        '    environment: \'node\',',
        "    include: ['src/**/*.test.ts'],",
        '  },',
        '});',
        '',
      ].join('\n');
      writeServerFile(vitestPath, vitestContent);
      serverFiles.push({ relativePath: 'project/vitest.config.ts', content: vitestContent, kind: 'server' });
      writtenPaths.push(vitestPath);

      // Test files — one per bounded context + health + middleware
      const testDir = join(serverDir.replace('/server', ''), '__tests__');
      mkdirSync(testDir, { recursive: true, mode: DIR_MODE });

      // Health endpoint test
      const healthTestContent = tsHealthTest();
      const healthTestPath = join(testDir, 'health.test.ts');
      writeServerFile(healthTestPath, healthTestContent);
      serverFiles.push({ relativePath: 'project/src/__tests__/health.test.ts', content: healthTestContent, kind: 'server' });
      writtenPaths.push(healthTestPath);

      // Per-context unit tests (mock-based, fast)
      for (const ctx of contexts) {
        const ctxSlug = snakeCase(ctx.name);
        const testContent = tsContextTest(ctx);
        const testPath = join(testDir, `${ctxSlug}.test.ts`);
        writeServerFile(testPath, testContent);
        serverFiles.push({ relativePath: `project/src/__tests__/${ctxSlug}.test.ts`, content: testContent, kind: 'server' });
        writtenPaths.push(testPath);
      }

      // ADR-055: Per-context integration tests (real SQLite, tests actual SQL)
      const integrationTestDir = join(projectDir, 'src', '__tests__', 'integration');
      mkdirSync(integrationTestDir, { recursive: true, mode: DIR_MODE });
      for (const ctx of contexts) {
        const ctxSlug = snakeCase(ctx.name);
        const integContent = tsContextIntegrationTest(ctx);
        const integPath = join(integrationTestDir, `${ctxSlug}.integration.test.ts`);
        writeServerFile(integPath, integContent);
        serverFiles.push({ relativePath: `project/src/__tests__/integration/${ctxSlug}.integration.test.ts`, content: integContent, kind: 'server' });
        writtenPaths.push(integPath);
      }

      const totalFiles = 8 + 1 + 1 + contexts.length; // server files + vitest + health test + context tests
      const finalGenSpan = endSpan(genSpan, 'ok', { filesGenerated: totalFiles, routeCount });
      emitSpan(finalGenSpan);

      const finalRootSpan = endSpan(rootSpan, 'ok', { framework, filesGenerated: 6, routeCount });
      emitSpan(finalRootSpan);

      const timing = Date.now() - startTime;
      const output: Phase4StageOutput = {
        stage: 'http-server-generation',
        status: 'completed',
        data: {
          framework,
          files: serverFiles,
          routeCount,
        } satisfies HttpServerOutput,
        artifacts: writtenPaths,
        timing,
        summary: `Generated ${serverFiles.length} server files (${routeCount} domain routes) using ${framework}`,
      };
      context.stageOutputs.set('http-server-generation', output);
      return output;
    }

    // Rust path (unchanged)
    const rustMainContent = rustMain();
    const rustMainPath = join(serverDir, 'main.rs');
    writeServerFile(rustMainPath, rustMainContent);
    serverFiles.push({ relativePath: 'project/src/server/main.rs', content: rustMainContent, kind: 'server' });
    writtenPaths.push(rustMainPath);

    const { content: rustRoutesContent, routeCount: rustRouteCount } = rustRoutes(contexts);
    const rustRoutesPath = join(serverDir, 'routes.rs');
    writeServerFile(rustRoutesPath, rustRoutesContent);
    serverFiles.push({ relativePath: 'project/src/server/routes.rs', content: rustRoutesContent, kind: 'server' });
    writtenPaths.push(rustRoutesPath);

    const rustMiddlewareContent = rustMiddleware();
    const rustMiddlewarePath = join(serverDir, 'middleware.rs');
    writeServerFile(rustMiddlewarePath, rustMiddlewareContent);
    serverFiles.push({ relativePath: 'project/src/server/middleware.rs', content: rustMiddlewareContent, kind: 'server' });
    writtenPaths.push(rustMiddlewarePath);

    const rustHealthContent = rustHealth();
    const rustHealthPath = join(serverDir, 'health.rs');
    writeServerFile(rustHealthPath, rustHealthContent);
    serverFiles.push({ relativePath: 'project/src/server/health.rs', content: rustHealthContent, kind: 'server' });
    writtenPaths.push(rustHealthPath);

    const finalGenSpan = endSpan(genSpan, 'ok', { filesGenerated: 4, routeCount: rustRouteCount });
    emitSpan(finalGenSpan);

    const finalRootSpan = endSpan(rootSpan, 'ok', { framework, filesGenerated: 4, routeCount: rustRouteCount });
    emitSpan(finalRootSpan);

    const timing = Date.now() - startTime;
    const output: Phase4StageOutput = {
      stage: 'http-server-generation',
      status: 'completed',
      data: {
        framework,
        files: serverFiles,
        routeCount: rustRouteCount,
      } satisfies HttpServerOutput,
      artifacts: writtenPaths,
      timing,
      summary: `Generated ${serverFiles.length} server files (${rustRouteCount} routes) using ${framework}`,
    };
    context.stageOutputs.set('http-server-generation', output);
    return output;
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    const errorSpan = endSpan(rootSpan, 'error', { error: message });
    emitSpan(errorSpan);

    const timing = Date.now() - startTime;
    const output: Phase4StageOutput = {
      stage: 'http-server-generation',
      status: 'failed',
      data: { error: message },
      artifacts: [],
      timing,
      summary: `HTTP server generation failed: ${message}`,
    };
    context.stageOutputs.set('http-server-generation', output);
    return output;
  }
}
